import { useEffect, useMemo, useState } from "react";

interface User {
  id: string;
  name: string;
  email: string;
}

type SortField = "name" | "email";

const DEBOUNCE_MS = 300;

export default function UserSearch() {
  const [query, setQuery] = useState("");
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [sortField, setSortField] = useState<SortField>("name");

  useEffect(() => {
    const term = query.trim();
    if (!term) {
      setUsers([]);
      setLoading(false);
      setError(null);
      return;
    }

    const controller = new AbortController();
    const timer = setTimeout(() => {
      setLoading(true);
      setError(null);
      fetch(`/api/users?q=${encodeURIComponent(term)}`, { signal: controller.signal })
        .then((res) => {
          if (!res.ok) {
            throw new Error(`Request failed with status ${res.status}`);
          }
          return res.json();
        })
        .then((data: User[]) => {
          setUsers(data);
        })
        .catch((err: unknown) => {
          if (err instanceof DOMException && err.name === "AbortError") {
            return;
          }
          setError(err instanceof Error ? err.message : "Failed to fetch users");
        })
        .finally(() => {
          setLoading(false);
        });
    }, DEBOUNCE_MS);

    return () => {
      clearTimeout(timer);
      controller.abort();
    };
  }, [query]);

  const sortedUsers = useMemo(() => {
    return [...users].sort((a, b) => a[sortField].localeCompare(b[sortField]));
  }, [users, sortField]);

  return (
    <div>
      <input
        type="text"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search users..."
        aria-label="Search users"
      />

      <div>
        <label>
          Sort by:{" "}
          <select
            value={sortField}
            onChange={(e) => setSortField(e.target.value as SortField)}
          >
            <option value="name">Name</option>
            <option value="email">Email</option>
          </select>
        </label>
      </div>

      {loading && <p role="status">Loading...</p>}
      {error && <p role="alert">Error: {error}</p>}

      {!loading && !error && query.trim() !== "" && (
        <p>
          {sortedUsers.length} result{sortedUsers.length === 1 ? "" : "s"}
        </p>
      )}

      <ul>
        {sortedUsers.map((user) => (
          <li key={user.id}>
            {user.name} ({user.email})
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useEffect, useRef, useState } from "react";

interface Metric {
  name: string;
  value: number;
  unit: string;
}

const POLL_INTERVAL_MS = 10_000;

export default function MetricsPanel() {
  const [metrics, setMetrics] = useState<Metric[]>([]);
  const [changedNames, setChangedNames] = useState<Set<string>>(new Set());
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const [secondsAgo, setSecondsAgo] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const previousValues = useRef<Map<string, number>>(new Map());

  useEffect(() => {
    let cancelled = false;
    let timeoutId: ReturnType<typeof setTimeout> | undefined;

    async function fetchMetrics() {
      try {
        const res = await fetch("/api/metrics");
        if (!res.ok) throw new Error(`Request failed: ${res.status}`);
        const data: Metric[] = await res.json();
        if (cancelled) return;

        const previous = previousValues.current;
        const nextChanged = new Set<string>();
        for (const metric of data) {
          const prevValue = previous.get(metric.name);
          if (prevValue !== undefined && prevValue !== metric.value) {
            nextChanged.add(metric.name);
          }
        }

        const nextPrevious = new Map<string, number>();
        for (const metric of data) {
          nextPrevious.set(metric.name, metric.value);
        }
        previousValues.current = nextPrevious;

        setMetrics(data);
        setChangedNames(nextChanged);
        setLastUpdated(new Date());
        setError(null);
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : "Failed to load metrics");
        }
      } finally {
        if (!cancelled) {
          scheduleNext();
        }
      }
    }

    function scheduleNext() {
      timeoutId = setTimeout(() => {
        if (document.hidden) {
          scheduleNext();
        } else {
          void fetchMetrics();
        }
      }, POLL_INTERVAL_MS);
    }

    function handleVisibilityChange() {
      if (!document.hidden) {
        void fetchMetrics();
        if (timeoutId !== undefined) clearTimeout(timeoutId);
      }
    }

    void fetchMetrics();
    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      cancelled = true;
      if (timeoutId !== undefined) clearTimeout(timeoutId);
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, []);

  useEffect(() => {
    if (!lastUpdated) return;
    const tick = () => {
      setSecondsAgo(Math.max(0, Math.floor((Date.now() - lastUpdated.getTime()) / 1000)));
    };
    tick();
    const intervalId = setInterval(tick, 1000);
    return () => clearInterval(intervalId);
  }, [lastUpdated]);

  return (
    <div className="metrics-panel">
      <div className="metrics-panel-header">
        <h2>Metrics</h2>
        <span className="metrics-panel-updated">
          {lastUpdated ? `last updated ${secondsAgo} second${secondsAgo === 1 ? "" : "s"} ago` : "loading…"}
        </span>
      </div>
      {error && <div className="metrics-panel-error">{error}</div>}
      <ul className="metrics-panel-list">
        {metrics.map((metric) => (
          <li
            key={metric.name}
            className={changedNames.has(metric.name) ? "metrics-panel-item changed" : "metrics-panel-item"}
          >
            <span className="metrics-panel-name">{metric.name}</span>
            <span className="metrics-panel-value">
              {metric.value}
              {metric.unit}
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useEffect, useMemo, useState } from "react";

interface User {
  id: string;
  name: string;
  email: string;
}

type SortField = "name" | "email";

const DEBOUNCE_MS = 300;

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.name === "string" &&
    typeof candidate.email === "string"
  );
}

function isUserArray(value: unknown): value is User[] {
  return Array.isArray(value) && value.every(isUser);
}

export default function UserSearch() {
  const [query, setQuery] = useState("");
  const [debouncedQuery, setDebouncedQuery] = useState("");
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [sortField, setSortField] = useState<SortField>("name");

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedQuery(query), DEBOUNCE_MS);
    return () => clearTimeout(timer);
  }, [query]);

  useEffect(() => {
    if (!debouncedQuery) {
      setUsers([]);
      setError(null);
      setLoading(false);
      return;
    }

    const controller = new AbortController();
    setLoading(true);
    setError(null);

    fetch(`/api/users?q=${encodeURIComponent(debouncedQuery)}`, {
      signal: controller.signal,
    })
      .then((res) => {
        if (!res.ok) {
          throw new Error(`Request failed with status ${res.status}`);
        }
        return res.json();
      })
      .then((responseBody: unknown) => {
        if (!isUserArray(responseBody)) {
          throw new Error("Unexpected response shape from /api/users");
        }
        setUsers(responseBody);
        setLoading(false);
      })
      .catch((err: unknown) => {
        if (err instanceof DOMException && err.name === "AbortError") {
          return;
        }
        setError(err instanceof Error ? err.message : "Failed to fetch users");
        setUsers([]);
        setLoading(false);
      });

    return () => controller.abort();
  }, [debouncedQuery]);

  const sortedUsers = useMemo(() => {
    return [...users].sort((a, b) => a[sortField].localeCompare(b[sortField]));
  }, [users, sortField]);

  return (
    <div>
      <input
        type="text"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search users..."
        aria-label="Search users"
      />

      <div>
        <label>
          Sort by:{" "}
          <select
            value={sortField}
            onChange={(e) => setSortField(e.target.value as SortField)}
          >
            <option value="name">Name</option>
            <option value="email">Email</option>
          </select>
        </label>
      </div>

      {loading && <div role="status">Loading...</div>}
      {error && <div role="alert">Error: {error}</div>}

      {!loading && !error && debouncedQuery && (
        <div>{sortedUsers.length} result{sortedUsers.length === 1 ? "" : "s"}</div>
      )}

      <ul>
        {sortedUsers.map((user) => (
          <li key={user.id}>
            {user.name} ({user.email})
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useEffect, useRef, useState } from "react";

interface Metric {
  name: string;
  value: number;
  unit: string;
}

const POLL_INTERVAL_MS = 10_000;
const CLOCK_TICK_MS = 1_000;

function isMetric(value: unknown): value is Metric {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.name === "string" &&
    typeof candidate.value === "number" &&
    typeof candidate.unit === "string"
  );
}

async function fetchMetrics(signal: AbortSignal): Promise<Metric[]> {
  const response = await fetch("/api/metrics", { signal });
  if (!response.ok) {
    throw new Error(`Failed to load metrics: ${response.status}`);
  }
  const payload: unknown = await response.json();
  if (!Array.isArray(payload) || !payload.every(isMetric)) {
    throw new Error("Received malformed metrics payload");
  }
  return payload;
}

export default function MetricsPanel() {
  const [metrics, setMetrics] = useState<Metric[]>([]);
  const [changedNames, setChangedNames] = useState<Set<string>>(new Set());
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [, setClockTick] = useState(0);

  const previousValuesRef = useRef<Map<string, number>>(new Map());

  useEffect(() => {
    let cancelled = false;
    let timeoutId: ReturnType<typeof setTimeout> | undefined;
    const controller = new AbortController();

    const scheduleNext = () => {
      if (cancelled) return;
      timeoutId = setTimeout(runIfVisible, POLL_INTERVAL_MS);
    };

    const load = async () => {
      try {
        const data = await fetchMetrics(controller.signal);
        if (cancelled) return;

        const previousValues = previousValuesRef.current;
        const nextChanged = new Set<string>();
        const nextValues = new Map<string, number>();
        for (const metric of data) {
          const previous = previousValues.get(metric.name);
          if (previous !== undefined && previous !== metric.value) {
            nextChanged.add(metric.name);
          }
          nextValues.set(metric.name, metric.value);
        }
        previousValuesRef.current = nextValues;

        setMetrics(data);
        setChangedNames(nextChanged);
        setLastUpdated(new Date());
        setError(null);
      } catch (err) {
        if (cancelled || (err instanceof DOMException && err.name === "AbortError")) return;
        setError(err instanceof Error ? err.message : "Failed to load metrics");
      } finally {
        scheduleNext();
      }
    };

    const runIfVisible = () => {
      if (document.visibilityState === "hidden") {
        scheduleNext();
        return;
      }
      void load();
    };

    const handleVisibilityChange = () => {
      if (document.visibilityState === "visible") {
        if (timeoutId !== undefined) clearTimeout(timeoutId);
        void load();
      }
    };

    document.addEventListener("visibilitychange", handleVisibilityChange);
    void load();

    return () => {
      cancelled = true;
      controller.abort();
      if (timeoutId !== undefined) clearTimeout(timeoutId);
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, []);

  useEffect(() => {
    if (!lastUpdated) return;
    const intervalId = setInterval(() => setClockTick((tick) => tick + 1), CLOCK_TICK_MS);
    return () => clearInterval(intervalId);
  }, [lastUpdated]);

  const secondsAgo = lastUpdated ? Math.max(0, Math.round((Date.now() - lastUpdated.getTime()) / 1000)) : null;

  return (
    <div className="metrics-panel">
      <div className="metrics-panel-header">
        <h2>Metrics</h2>
        {secondsAgo !== null && (
          <span className="metrics-panel-updated">
            Last updated {secondsAgo} second{secondsAgo === 1 ? "" : "s"} ago
          </span>
        )}
      </div>
      {error && <div className="metrics-panel-error">{error}</div>}
      <ul className="metrics-panel-list">
        {metrics.map((metric) => (
          <li
            key={metric.name}
            className={changedNames.has(metric.name) ? "metric-item metric-item-changed" : "metric-item"}
          >
            <span className="metric-name">{metric.name}</span>
            <span className="metric-value">
              {metric.value}
              {metric.unit}
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useState, FormEvent } from "react";

type FormFields = "name" | "email" | "password" | "confirmPassword" | "acceptTerms";

type FormValues = {
  name: string;
  email: string;
  password: string;
  confirmPassword: string;
  acceptTerms: boolean;
};

type FieldErrors = Partial<Record<FormFields, string>>;

const INITIAL_VALUES: FormValues = {
  name: "",
  email: "",
  password: "",
  confirmPassword: "",
  acceptTerms: false,
};

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validate(values: FormValues): FieldErrors {
  const errors: FieldErrors = {};

  if (!values.name.trim()) {
    errors.name = "Name is required.";
  }

  if (!values.email.trim()) {
    errors.email = "Email is required.";
  } else if (!EMAIL_PATTERN.test(values.email)) {
    errors.email = "Enter a valid email address.";
  }

  if (!values.password) {
    errors.password = "Password is required.";
  } else if (values.password.length < 8) {
    errors.password = "Password must be at least 8 characters.";
  }

  if (!values.confirmPassword) {
    errors.confirmPassword = "Please confirm your password.";
  } else if (values.confirmPassword !== values.password) {
    errors.confirmPassword = "Passwords do not match.";
  }

  if (!values.acceptTerms) {
    errors.acceptTerms = "You must accept the terms to continue.";
  }

  return errors;
}

type SignupSuccessResponse = { id: string };
type SignupErrorResponse = { errors: Partial<Record<FormFields, string>> };

function isSignupErrorResponse(value: unknown): value is SignupErrorResponse {
  return (
    typeof value === "object" &&
    value !== null &&
    "errors" in value &&
    typeof (value as { errors: unknown }).errors === "object"
  );
}

export default function SignupForm() {
  const [values, setValues] = useState<FormValues>(INITIAL_VALUES);
  const [errors, setErrors] = useState<FieldErrors>({});
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [accountId, setAccountId] = useState<string | null>(null);

  function updateField<K extends keyof FormValues>(field: K, value: FormValues[K]) {
    setValues((prev) => ({ ...prev, [field]: value }));
    setErrors((prev) => ({ ...prev, [field]: undefined }));
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSubmitError(null);

    const validationErrors = validate(values);
    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      return;
    }

    setSubmitting(true);
    try {
      const response = await fetch("/api/signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: values.name,
          email: values.email,
          password: values.password,
          acceptTerms: values.acceptTerms,
        }),
      });

      const data: unknown = await response.json();

      if (!response.ok) {
        if (isSignupErrorResponse(data)) {
          setErrors(data.errors);
        } else {
          setSubmitError("Something went wrong. Please try again.");
        }
        return;
      }

      const { id } = data as SignupSuccessResponse;
      setAccountId(id);
      setValues(INITIAL_VALUES);
      setErrors({});
    } catch {
      setSubmitError("Network error. Please try again.");
    } finally {
      setSubmitting(false);
    }
  }

  if (accountId) {
    return (
      <div role="status">
        <p>Account created successfully! Your account id is {accountId}.</p>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      <div>
        <label htmlFor="name">Name</label>
        <input
          id="name"
          type="text"
          value={values.name}
          onChange={(e) => updateField("name", e.target.value)}
          aria-invalid={Boolean(errors.name)}
          aria-describedby={errors.name ? "name-error" : undefined}
        />
        {errors.name && <span id="name-error">{errors.name}</span>}
      </div>

      <div>
        <label htmlFor="email">Email</label>
        <input
          id="email"
          type="email"
          value={values.email}
          onChange={(e) => updateField("email", e.target.value)}
          aria-invalid={Boolean(errors.email)}
          aria-describedby={errors.email ? "email-error" : undefined}
        />
        {errors.email && <span id="email-error">{errors.email}</span>}
      </div>

      <div>
        <label htmlFor="password">Password</label>
        <input
          id="password"
          type="password"
          value={values.password}
          onChange={(e) => updateField("password", e.target.value)}
          aria-invalid={Boolean(errors.password)}
          aria-describedby={errors.password ? "password-error" : undefined}
        />
        {errors.password && <span id="password-error">{errors.password}</span>}
      </div>

      <div>
        <label htmlFor="confirmPassword">Confirm Password</label>
        <input
          id="confirmPassword"
          type="password"
          value={values.confirmPassword}
          onChange={(e) => updateField("confirmPassword", e.target.value)}
          aria-invalid={Boolean(errors.confirmPassword)}
          aria-describedby={errors.confirmPassword ? "confirmPassword-error" : undefined}
        />
        {errors.confirmPassword && <span id="confirmPassword-error">{errors.confirmPassword}</span>}
      </div>

      <div>
        <label htmlFor="acceptTerms">
          <input
            id="acceptTerms"
            type="checkbox"
            checked={values.acceptTerms}
            onChange={(e) => updateField("acceptTerms", e.target.checked)}
            aria-invalid={Boolean(errors.acceptTerms)}
            aria-describedby={errors.acceptTerms ? "acceptTerms-error" : undefined}
          />
          I accept the terms and conditions
        </label>
        {errors.acceptTerms && <span id="acceptTerms-error">{errors.acceptTerms}</span>}
      </div>

      {submitError && <p role="alert">{submitError}</p>}

      <button type="submit" disabled={submitting}>
        {submitting ? "Signing up..." : "Sign up"}
      </button>
    </form>
  );
}

import { useCallback, useEffect, useRef, useState, type FormEvent } from "react";

interface ChatMessage {
  id: string;
  author: string;
  text: string;
  sentAt: string;
}

function isChatMessage(value: unknown): value is ChatMessage {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  return (
    typeof v.id === "string" &&
    typeof v.author === "string" &&
    typeof v.text === "string" &&
    typeof v.sentAt === "string"
  );
}

const RECONNECT_DELAY_MS = 2000;

export interface ChatRoomProps {
  roomId: string;
}

export function ChatRoom({ roomId }: ChatRoomProps) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [draft, setDraft] = useState("");
  const [isReconnecting, setIsReconnecting] = useState(false);

  const socketRef = useRef<WebSocket | null>(null);
  const reconnectTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const messagesEndRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    let cancelled = false;
    setMessages([]);
    setIsReconnecting(false);

    const connect = () => {
      if (cancelled) return;

      const socket = new WebSocket(`wss://chat.example.com/rooms/${encodeURIComponent(roomId)}`);
      socketRef.current = socket;

      socket.addEventListener("open", () => {
        if (cancelled) return;
        setIsReconnecting(false);
      });

      socket.addEventListener("message", (event: MessageEvent) => {
        if (cancelled) return;
        try {
          const parsed = JSON.parse(event.data as string);
          if (isChatMessage(parsed)) {
            setMessages((prev) => [...prev, parsed]);
          }
        } catch {
          // ignore malformed payloads
        }
      });

      const scheduleReconnect = () => {
        if (cancelled) return;
        setIsReconnecting(true);
        reconnectTimerRef.current = setTimeout(connect, RECONNECT_DELAY_MS);
      };

      socket.addEventListener("close", scheduleReconnect);
      socket.addEventListener("error", () => {
        socket.close();
      });
    };

    connect();

    return () => {
      cancelled = true;
      if (reconnectTimerRef.current !== null) {
        clearTimeout(reconnectTimerRef.current);
        reconnectTimerRef.current = null;
      }
      const socket = socketRef.current;
      if (socket) {
        socket.onclose = null;
        socket.onerror = null;
        socket.close();
        socketRef.current = null;
      }
    };
  }, [roomId]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const sendMessage = useCallback(
    (event: FormEvent<HTMLFormElement>) => {
      event.preventDefault();
      const text = draft.trim();
      const socket = socketRef.current;
      if (!text || !socket || socket.readyState !== WebSocket.OPEN) return;

      socket.send(
        JSON.stringify({
          id: crypto.randomUUID(),
          author: "me",
          text,
          sentAt: new Date().toISOString(),
        }),
      );
      setDraft("");
    },
    [draft],
  );

  return (
    <div className="chat-room">
      {isReconnecting && <div className="chat-room__banner">Reconnecting…</div>}
      <div className="chat-room__messages">
        {messages.map((message) => (
          <div key={message.id} className="chat-room__message">
            <span className="chat-room__author">{message.author}</span>
            <span className="chat-room__text">{message.text}</span>
            <span className="chat-room__time">{new Date(message.sentAt).toLocaleTimeString()}</span>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>
      <form className="chat-room__composer" onSubmit={sendMessage}>
        <input
          type="text"
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          placeholder="Type a message…"
        />
        <button type="submit">Send</button>
      </form>
    </div>
  );
}

export default ChatRoom;

