    setMessages([]);
    setIsReconnecting(false);

    const connect = () => {
      if (cancelled) return;

      const socket = new WebSocket(`wss://chat.example.com/rooms/${roomId}`);
      socketRef.current = socket;

      socket.onopen = () => {
        if (cancelled) return;
        setIsReconnecting(false);
      };

      socket.onmessage = (event) => {
        if (cancelled) return;
        try {
          const parsed: unknown = JSON.parse(event.data);
          if (isChatMessage(parsed)) {
            setMessages((prev) => [...prev, parsed]);
          }
        } catch (error) {
          console.warn("Ignoring malformed chat message", error);
        }
      };

      socket.onclose = () => {
        if (cancelled) return;
        setIsReconnecting(true);
        reconnectTimerRef.current = setTimeout(connect, RECONNECT_DELAY_MS);
      };

      socket.onerror = () => {
        socket.close();
      };
    };

    connect();

    return () => {
      cancelled = true;
      if (reconnectTimerRef.current !== null) {
        clearTimeout(reconnectTimerRef.current);
        reconnectTimerRef.current = null;
      }
      const socket = socketRef.current;
      if (socket) {
        socket.onopen = null;
        socket.onmessage = null;
        socket.onclose = null;
        socket.onerror = null;
        socket.close();
        socketRef.current = null;
      }
    };
  }, [roomId]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleSend = (event: React.FormEvent) => {
    event.preventDefault();
    const text = draft.trim();
    const socket = socketRef.current;
    if (!text || !socket || socket.readyState !== WebSocket.OPEN) return;

    socket.send(JSON.stringify({ text }));
    setDraft("");
  };

  return (
    <div className="chat-room">
      {isReconnecting && (
        <div className="chat-room__banner" role="status">
          Reconnecting…
        </div>
      )}
      <div className="chat-room__messages">
        {messages.map((message) => (
          <div key={message.id} className="chat-room__message">
            <span className="chat-room__author">{message.author}</span>
            <span className="chat-room__text">{message.text}</span>
            <span className="chat-room__time">
              {new Date(message.sentAt).toLocaleTimeString()}
            </span>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>
      <form className="chat-room__composer" onSubmit={handleSend}>
        <input
          type="text"
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          placeholder="Type a message…"
        />
        <button type="submit">Send</button>
      </form>
    </div>
  );
}

import { useState, type ChangeEvent, type FormEvent } from "react";

interface FormValues {
  name: string;
  email: string;
  password: string;
  confirmPassword: string;
  acceptTerms: boolean;
}

type FieldName = keyof FormValues;

type FieldErrors = Partial<Record<FieldName, string>>;

const initialValues: FormValues = {
  name: "",
  email: "",
  password: "",
  confirmPassword: "",
  acceptTerms: false,
};

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validate(values: FormValues): FieldErrors {
  const errors: FieldErrors = {};

  if (!values.name.trim()) {
    errors.name = "Name is required.";
  }

  if (!values.email.trim()) {
    errors.email = "Email is required.";
  } else if (!EMAIL_PATTERN.test(values.email)) {
    errors.email = "Enter a valid email address.";
  }

  if (!values.password) {
    errors.password = "Password is required.";
  } else if (values.password.length < 8) {
    errors.password = "Password must be at least 8 characters.";
  }

  if (!values.confirmPassword) {
    errors.confirmPassword = "Please confirm your password.";
  } else if (values.confirmPassword !== values.password) {
    errors.confirmPassword = "Passwords do not match.";
  }

  if (!values.acceptTerms) {
    errors.acceptTerms = "You must accept the terms to continue.";
  }

  return errors;
}

function isFieldErrors(value: unknown): value is Record<string, string> {
  if (typeof value !== "object" || value === null) {
    return false;
  }
  return Object.values(value as Record<string, unknown>).every(
    (message) => typeof message === "string",
  );
}

export default function SignupForm() {
  const [values, setValues] = useState<FormValues>(initialValues);
  const [clientErrors, setClientErrors] = useState<FieldErrors>({});
  const [serverErrors, setServerErrors] = useState<FieldErrors>({});
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [successId, setSuccessId] = useState<string | null>(null);

  const errors: FieldErrors = { ...serverErrors, ...clientErrors };

  function handleChange(event: ChangeEvent<HTMLInputElement>) {
    const { name, value, type, checked } = event.target;
    const field = name as FieldName;

    setValues((prev) => ({
      ...prev,
      [field]: type === "checkbox" ? checked : value,
    }));

    setClientErrors((prev) => {
      if (!prev[field]) return prev;
      const next = { ...prev };
      delete next[field];
      return next;
    });
    setServerErrors((prev) => {
      if (!prev[field]) return prev;
      const next = { ...prev };
      delete next[field];
      return next;
    });
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();

    setSubmitError(null);
    setSuccessId(null);

    const validationErrors = validate(values);
    if (Object.keys(validationErrors).length > 0) {
      setClientErrors(validationErrors);
      return;
    }

    setClientErrors({});
    setServerErrors({});
    setSubmitting(true);

    try {
      const response = await fetch("/api/signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: values.name,
          email: values.email,
          password: values.password,
          acceptTerms: values.acceptTerms,
        }),
      });

      const responseBody: unknown = await response.json().catch(() => null);

      if (response.ok) {
        const accountId =
          responseBody && typeof responseBody === "object" && "id" in responseBody
            ? String((responseBody as { id: unknown }).id)
            : "";
        setSuccessId(accountId);
        setValues(initialValues);
      } else {
        const fieldErrors =
          responseBody && typeof responseBody === "object" && "errors" in responseBody
            ? (responseBody as { errors: unknown }).errors
            : null;

        if (isFieldErrors(fieldErrors)) {
          setServerErrors(fieldErrors);
        } else {
          setSubmitError("Something went wrong. Please try again.");
        }
      }
    } catch {
      setSubmitError("Something went wrong. Please try again.");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      <h1>Create an account</h1>

      {successId && (
        <p role="status">Account created successfully! Your account id is {successId}.</p>
      )}
      {submitError && <p role="alert">{submitError}</p>}

      <div>
        <label htmlFor="name">Name</label>
        <input
          id="name"
          name="name"
          type="text"
          value={values.name}
          onChange={handleChange}
          aria-invalid={Boolean(errors.name)}
          aria-describedby={errors.name ? "name-error" : undefined}
        />
        {errors.name && <span id="name-error">{errors.name}</span>}
      </div>

      <div>
        <label htmlFor="email">Email</label>
        <input
          id="email"
          name="email"
          type="email"
          value={values.email}
          onChange={handleChange}
          aria-invalid={Boolean(errors.email)}
          aria-describedby={errors.email ? "email-error" : undefined}
        />
        {errors.email && <span id="email-error">{errors.email}</span>}
      </div>

      <div>
        <label htmlFor="password">Password</label>
        <input
          id="password"
          name="password"
          type="password"
          value={values.password}
          onChange={handleChange}
          aria-invalid={Boolean(errors.password)}
          aria-describedby={errors.password ? "password-error" : undefined}
        />
        {errors.password && <span id="password-error">{errors.password}</span>}
      </div>

      <div>
        <label htmlFor="confirmPassword">Confirm password</label>
        <input
          id="confirmPassword"
          name="confirmPassword"
          type="password"
          value={values.confirmPassword}
          onChange={handleChange}
          aria-invalid={Boolean(errors.confirmPassword)}
          aria-describedby={errors.confirmPassword ? "confirmPassword-error" : undefined}
        />
        {errors.confirmPassword && (
          <span id="confirmPassword-error">{errors.confirmPassword}</span>
        )}
      </div>

      <div>
        <label htmlFor="acceptTerms">
          <input
            id="acceptTerms"
            name="acceptTerms"
            type="checkbox"
            checked={values.acceptTerms}
            onChange={handleChange}
            aria-invalid={Boolean(errors.acceptTerms)}
            aria-describedby={errors.acceptTerms ? "acceptTerms-error" : undefined}
          />
          I accept the terms and conditions
        </label>
        {errors.acceptTerms && <span id="acceptTerms-error">{errors.acceptTerms}</span>}
      </div>

      <button type="submit" disabled={submitting}>
        {submitting ? "Signing up..." : "Sign up"}
      </button>
    </form>
  );
}

import { useEffect, useMemo, useState } from "react";

interface TodoItem {
  id: string;
  text: string;
  done: boolean;
}

type Filter = "all" | "active" | "done";

const STORAGE_KEY = "todo-board:items";

function loadItems(): TodoItem[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed;
  } catch {
    return [];
  }
}

export default function TodoBoard() {
  const [items, setItems] = useState<TodoItem[]>(() => loadItems());
  const [filter, setFilter] = useState<Filter>("all");
  const [newText, setNewText] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingText, setEditingText] = useState("");

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
  }, [items]);

  const remainingCount = useMemo(
    () => items.filter((item) => !item.done).length,
    [items],
  );

  const visibleItems = useMemo(() => {
    switch (filter) {
      case "active":
        return items.filter((item) => !item.done);
      case "done":
        return items.filter((item) => item.done);
      default:
        return items;
    }
  }, [items, filter]);

  function addItem() {
    const text = newText.trim();
    if (!text) return;
    const item: TodoItem = {
      id: crypto.randomUUID(),
      text,
      done: false,
    };
    setItems((prev) => [...prev, item]);
    setNewText("");
  }

  function toggleDone(id: string) {
    setItems((prev) =>
      prev.map((item) =>
        item.id === id ? { ...item, done: !item.done } : item,
      ),
    );
  }

  function deleteItem(id: string) {
    setItems((prev) => prev.filter((item) => item.id !== id));
    if (editingId === id) {
      setEditingId(null);
      setEditingText("");
    }
  }

  function startEditing(item: TodoItem) {
    setEditingId(item.id);
    setEditingText(item.text);
  }

  function cancelEditing() {
    setEditingId(null);
    setEditingText("");
  }

  function commitEditing() {
    const text = editingText.trim();
    if (editingId === null) return;
    if (!text) {
      cancelEditing();
      return;
    }
    setItems((prev) =>
      prev.map((item) =>
        item.id === editingId ? { ...item, text } : item,
      ),
    );
    cancelEditing();
  }

  function moveItem(id: string, direction: -1 | 1) {
    setItems((prev) => {
      const index = prev.findIndex((item) => item.id === id);
      const targetIndex = index + direction;
      if (index === -1 || targetIndex < 0 || targetIndex >= prev.length) {
        return prev;
      }
      const next = [...prev];
      [next[index], next[targetIndex]] = [next[targetIndex], next[index]];
      return next;
    });
  }

  return (
    <div>
      <h1>Todo Board</h1>

      <form
        onSubmit={(e) => {
          e.preventDefault();
          addItem();
        }}
      >
        <input
          type="text"
          value={newText}
          onChange={(e) => setNewText(e.target.value)}
          placeholder="Add a new item"
          aria-label="New todo text"
        />
        <button type="submit">Add</button>
      </form>

      <div role="group" aria-label="Filter items">
        <button
          type="button"
          disabled={filter === "all"}
          onClick={() => setFilter("all")}
        >
          All
        </button>
        <button
          type="button"
          disabled={filter === "active"}
          onClick={() => setFilter("active")}
        >
          Active
        </button>
        <button
          type="button"
          disabled={filter === "done"}
          onClick={() => setFilter("done")}
        >
          Done
        </button>
      </div>

      <p>{remainingCount} item{remainingCount === 1 ? "" : "s"} remaining</p>

      <ul>
        {visibleItems.map((item) => {
          const index = items.findIndex((i) => i.id === item.id);
          const isEditing = editingId === item.id;
          return (
            <li key={item.id}>
              <input
                type="checkbox"
                checked={item.done}
                onChange={() => toggleDone(item.id)}
                aria-label={`Mark "${item.text}" as ${item.done ? "active" : "done"}`}
              />

              {isEditing ? (
                <>
                  <input
                    type="text"
                    value={editingText}
                    onChange={(e) => setEditingText(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === "Enter") commitEditing();
                      if (e.key === "Escape") cancelEditing();
                    }}
                    autoFocus
                  />
                  <button type="button" onClick={commitEditing}>
                    Save
                  </button>
                  <button type="button" onClick={cancelEditing}>
                    Cancel
                  </button>
                </>
              ) : (
                <>
                  <span
                    style={{
                      textDecoration: item.done ? "line-through" : "none",
                    }}
                  >
                    {item.text}
                  </span>
                  <button type="button" onClick={() => startEditing(item)}>
                    Edit
                  </button>
                </>
              )}

              <button
                type="button"
                onClick={() => moveItem(item.id, -1)}
                disabled={index <= 0}
                aria-label={`Move "${item.text}" up`}
              >
                ↑
              </button>
              <button
                type="button"
                onClick={() => moveItem(item.id, 1)}
                disabled={index === -1 || index >= items.length - 1}
                aria-label={`Move "${item.text}" down`}
              >
                ↓
              </button>

              <button type="button" onClick={() => deleteItem(item.id)}>
                Delete
              </button>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

import { useEffect, useMemo, useState, type FormEvent, type KeyboardEvent } from "react";

interface Todo {
  id: string;
  text: string;
  done: boolean;
}

type Filter = "all" | "active" | "done";

const STORAGE_KEY = "todo-board:items";

function loadTodos(): Todo[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(
      (item): item is Todo =>
        typeof item === "object" &&
        item !== null &&
        typeof item.id === "string" &&
        typeof item.text === "string" &&
        typeof item.done === "boolean"
    );
  } catch {
    return [];
  }
}

function createId(): string {
  return `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

export default function TodoBoard() {
  const [todos, setTodos] = useState<Todo[]>(() => loadTodos());
  const [newText, setNewText] = useState("");
  const [filter, setFilter] = useState<Filter>("all");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingText, setEditingText] = useState("");

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }, [todos]);

  const remainingCount = useMemo(() => todos.filter((todo) => !todo.done).length, [todos]);

  const visibleTodos = useMemo(() => {
    switch (filter) {
      case "active":
        return todos.filter((todo) => !todo.done);
      case "done":
        return todos.filter((todo) => todo.done);
      default:
        return todos;
    }
  }, [todos, filter]);

  function handleAddTodo(event: FormEvent) {
    event.preventDefault();
    const text = newText.trim();
    if (!text) return;
    setTodos((prev) => [...prev, { id: createId(), text, done: false }]);
    setNewText("");
  }

  function toggleDone(id: string) {
    setTodos((prev) =>
      prev.map((todo) => (todo.id === id ? { ...todo, done: !todo.done } : todo))
    );
  }

  function deleteTodo(id: string) {
    setTodos((prev) => prev.filter((todo) => todo.id !== id));
    if (editingId === id) {
      setEditingId(null);
      setEditingText("");
    }
  }

  function startEditing(todo: Todo) {
    setEditingId(todo.id);
    setEditingText(todo.text);
  }

  function cancelEditing() {
    setEditingId(null);
    setEditingText("");
  }

  function commitEditing() {
    const text = editingText.trim();
    if (editingId === null) return;
    if (!text) {
      deleteTodo(editingId);
      return;
    }
    setTodos((prev) =>
      prev.map((todo) => (todo.id === editingId ? { ...todo, text } : todo))
    );
    setEditingId(null);
    setEditingText("");
  }

  function handleEditKeyDown(event: KeyboardEvent<HTMLInputElement>) {
    if (event.key === "Enter") {
      commitEditing();
    } else if (event.key === "Escape") {
      cancelEditing();
    }
  }

  function moveTodo(id: string, direction: -1 | 1) {
    setTodos((prev) => {
      const index = prev.findIndex((todo) => todo.id === id);
      const targetIndex = index + direction;
      if (index === -1 || targetIndex < 0 || targetIndex >= prev.length) return prev;
      const next = [...prev];
      const [moved] = next.splice(index, 1);
      next.splice(targetIndex, 0, moved);
      return next;
    });
  }

  return (
    <div className="todo-board">
      <h1>Todo Board</h1>

      <form onSubmit={handleAddTodo} className="todo-add-form">
        <input
          type="text"
          value={newText}
          onChange={(event) => setNewText(event.target.value)}
          placeholder="Add a new todo"
          aria-label="New todo text"
        />
        <button type="submit">Add</button>
      </form>

      <div className="todo-filters" role="group" aria-label="Filter todos">
        {(["all", "active", "done"] as const).map((option) => (
          <button
            key={option}
            type="button"
            onClick={() => setFilter(option)}
            aria-pressed={filter === option}
            disabled={filter === option}
          >
            {option[0].toUpperCase() + option.slice(1)}
          </button>
        ))}
      </div>

      <ul className="todo-list">
        {visibleTodos.map((todo) => {
          const index = todos.findIndex((item) => item.id === todo.id);
          const isEditing = editingId === todo.id;
          return (
            <li key={todo.id} className="todo-item">
              <input
                type="checkbox"
                checked={todo.done}
                onChange={() => toggleDone(todo.id)}
                aria-label={`Mark "${todo.text}" as ${todo.done ? "active" : "done"}`}
              />

              {isEditing ? (
                <input
                  type="text"
                  value={editingText}
                  onChange={(event) => setEditingText(event.target.value)}
                  onBlur={commitEditing}
                  onKeyDown={handleEditKeyDown}
                  autoFocus
                  aria-label="Edit todo text"
                />
              ) : (
                <span
                  className="todo-text"
                  style={{ textDecoration: todo.done ? "line-through" : "none" }}
                  onDoubleClick={() => startEditing(todo)}
                >
                  {todo.text}
                </span>
              )}

              <div className="todo-actions">
                {!isEditing && <button type="button" onClick={() => startEditing(todo)}>Edit</button>}
                <button
                  type="button"
                  onClick={() => moveTodo(todo.id, -1)}
                  disabled={index <= 0}
                  aria-label={`Move "${todo.text}" up`}
                >
                  ↑
                </button>
                <button
                  type="button"
                  onClick={() => moveTodo(todo.id, 1)}
                  disabled={index === -1 || index >= todos.length - 1}
                  aria-label={`Move "${todo.text}" down`}
                >
                  ↓
                </button>
                <button type="button" onClick={() => deleteTodo(todo.id)}>Delete</button>
              </div>
            </li>
          );
        })}
      </ul>

      <p className="todo-count">
        {remainingCount} item{remainingCount === 1 ? "" : "s"} remaining
      </p>
    </div>
  );
}

import { useEffect, useRef, useState } from "react";
import type { User } from "./ProfileEditor";

export interface UseUserProfilesResult {
  profiles: Record<string, User>;
  loading: boolean;
  errors: Record<string, string>;
}

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) {
    return false;
  }
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.displayName === "string" &&
    typeof candidate.bio === "string" &&
    typeof candidate.avatarUrl === "string"
  );
}

export function useUserProfiles(userIds: string[]): UseUserProfilesResult {
  const [profiles, setProfiles] = useState<Record<string, User>>({});
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(userIds.length > 0);
  const idsKey = userIds.join(",");
  const requestIdRef = useRef(0);

  useEffect(() => {
    const ids = idsKey.length > 0 ? idsKey.split(",") : [];
    const requestId = ++requestIdRef.current;

    setProfiles({});
    setErrors({});
    setLoading(ids.length > 0);

    if (ids.length === 0) {
      return;
    }

    type FetchResult = { id: string; user: User } | { id: string; error: string };

    Promise.all(
      ids.map(async (id): Promise<FetchResult> => {
        try {
          const response = await fetch(`/api/users/${encodeURIComponent(id)}`);
          if (!response.ok) {
            throw new Error(`Request failed with status ${response.status}`);
          }
          const responseBody: unknown = await response.json();
          if (!isUser(responseBody)) {
            throw new Error("Received malformed profile data");
          }
          return { id, user: responseBody };
        } catch (err) {
          const message = err instanceof Error ? err.message : "Failed to load profile";
          return { id, error: message };
        }
      })
    ).then((results) => {
      if (requestIdRef.current !== requestId) {
        return;
      }

      const nextProfiles: Record<string, User> = {};
      const nextErrors: Record<string, string> = {};
      for (const result of results) {
        if ("user" in result) {
          nextProfiles[result.id] = result.user;
        } else {
          nextErrors[result.id] = result.error;
        }
      }

      setProfiles(nextProfiles);
      setErrors(nextErrors);
      setLoading(false);
    });
  }, [idsKey]);

  return { profiles, loading, errors };
}

import { useState } from "react";

export interface User {
  id: string;
  displayName: string;
  bio: string;
  avatarUrl: string;
}

export interface ProfileEditorProps {
  user: User;
  onSave: (user: User) => Promise<void>;
}

export function ProfileEditor({ user, onSave }: ProfileEditorProps) {
  const [displayName, setDisplayName] = useState(user.displayName);
  const [bio, setBio] = useState(user.bio);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const hasChanges = displayName !== user.displayName || bio !== user.bio;

  function handleReset() {
    setDisplayName(user.displayName);
    setBio(user.bio);
    setError(null);
  }

  async function handleSave() {
    setSaving(true);
    setError(null);
    try {
      await onSave({ ...user, displayName, bio });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to save profile");
    } finally {
      setSaving(false);
    }
  }

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        void handleSave();
      }}
    >
      <div>
        <img src={user.avatarUrl} alt={`${user.displayName}'s avatar`} width={64} height={64} />
      </div>

      <label htmlFor="displayName">Display name</label>
      <input
        id="displayName"
        type="text"
        value={displayName}
        onChange={(e) => setDisplayName(e.target.value)}
        disabled={saving}
      />

      <label htmlFor="bio">Bio</label>
      <textarea
        id="bio"
        value={bio}
        onChange={(e) => setBio(e.target.value)}
        disabled={saving}
      />

      <p>{hasChanges ? "Unsaved changes" : "No unsaved changes"}</p>
      {error !== null && <p role="alert">{error}</p>}

      <button type="submit" disabled={saving || !hasChanges}>
        {saving ? "Saving…" : "Save"}
      </button>
      <button type="button" onClick={handleReset} disabled={saving || !hasChanges}>
        Reset
      </button>
    </form>
  );
}

import { useEffect, useState } from "react";
import type { User } from "./ProfileEditor";

export interface UseUserProfilesResult {
  profiles: Record<string, User>;
  loading: boolean;
  errors: Record<string, string>;
}

type ProfileFetchResult =
  | { id: string; ok: true; user: User }
  | { id: string; ok: false; error: string };

export function useUserProfiles(ids: string[]): UseUserProfilesResult {
  const [profiles, setProfiles] = useState<Record<string, User>>({});
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(ids.length > 0);

  const idsKey = ids.join(",");

  useEffect(() => {
    if (ids.length === 0) {
      setProfiles({});
      setErrors({});
      setLoading(false);
      return;
    }

    let cancelled = false;
    setLoading(true);

    Promise.all(
      ids.map(async (id): Promise<ProfileFetchResult> => {
        try {
          const response = await fetch(`/api/users/${id}`);
          if (!response.ok) {
            throw new Error(`Failed to load user ${id}: ${response.status}`);
          }
          const user = (await response.json()) as User;
          return { id, ok: true, user };
        } catch (err) {
          const message = err instanceof Error ? err.message : `Failed to load user ${id}`;
          return { id, ok: false, error: message };
        }
      }),
    ).then((results) => {
      if (cancelled) return;

      const nextProfiles: Record<string, User> = {};
      const nextErrors: Record<string, string> = {};
      for (const result of results) {
        if (result.ok) {
          nextProfiles[result.id] = result.user;
        } else {
          nextErrors[result.id] = result.error;
        }
      }

      setProfiles(nextProfiles);
      setErrors(nextErrors);
      setLoading(false);
    });

    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [idsKey]);

  return { profiles, loading, errors };
}

