import Combine
import Foundation
import SwiftUI

struct SearchResult: Identifiable, Decodable, Hashable {
    let id: String
    let title: String
    let subtitle: String
}

@MainActor
final class SearchViewModel: ObservableObject {
    private static let debounceMilliseconds = 300
    private static let successStatusCodes = 200..<300

    nonisolated private static let defaultBaseURL: URL = {
        guard let url = URL(string: "https://api.example.com/search") else {
            fatalError("SearchViewModel.defaultBaseURL: invalid hardcoded URL string")
        }
        return url
    }()

    @Published var query: String = ""
    @Published private(set) var results: [SearchResult] = []
    @Published private(set) var isLoading: Bool = false
    @Published private(set) var errorMessage: String?

    private var searchTask: Task<Void, Never>?
    private var cancellables: Set<AnyCancellable> = []
    private let session: URLSession
    private let baseURL: URL

    init(
        session: URLSession = .shared,
        baseURL: URL = SearchViewModel.defaultBaseURL
    ) {
        self.session = session
        self.baseURL = baseURL

        $query
            .removeDuplicates()
            .debounce(for: .milliseconds(Self.debounceMilliseconds), scheduler: RunLoop.main)
            .sink { [weak self] text in
                self?.search(for: text)
            }
            .store(in: &cancellables)
    }

    private func search(for text: String) {
        searchTask?.cancel()

        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            isLoading = false
            errorMessage = nil
            results = []
            return
        }

        isLoading = true
        errorMessage = nil

        var currentTask: Task<Void, Never>?
        currentTask = Task { [weak self] in
            guard let self else { return }
            defer {
                if self.searchTask == currentTask {
                    self.isLoading = false
                }
            }

            do {
                let fetched = try await self.fetchResults(query: trimmed)
                guard self.searchTask == currentTask else { return }
                self.results = fetched
            } catch is CancellationError {
                // Superseded by a newer search; the defer above only resets
                // isLoading if this task is still the current one.
                return
            } catch {
                guard self.searchTask == currentTask else { return }
                self.results = []
                self.errorMessage = error.localizedDescription
            }
        }
        searchTask = currentTask
    }

    private func fetchResults(query: String) async throws -> [SearchResult] {
        guard var components = URLComponents(url: baseURL, resolvingAgainstBaseURL: false) else {
            throw URLError(.badURL)
        }
        components.queryItems = [URLQueryItem(name: "q", value: query)]
        guard let url = components.url else {
            throw URLError(.badURL)
        }

        let (data, response) = try await session.data(from: url)

        if let httpResponse = response as? HTTPURLResponse,
           !Self.successStatusCodes.contains(httpResponse.statusCode) {
            throw URLError(.badServerResponse)
        }

        return try JSONDecoder().decode([SearchResult].self, from: data)
    }
}

struct SearchScreen: View {
    @StateObject private var viewModel = SearchViewModel()

    var body: some View {
        VStack(spacing: 0) {
            TextField("Search", text: $viewModel.query)
                .textFieldStyle(.roundedBorder)
                .padding()

            content
        }
        .frame(minWidth: 320, minHeight: 400)
    }

    @ViewBuilder
    private var content: some View {
        if viewModel.isLoading {
            ProgressView("Searching…")
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else if let errorMessage = viewModel.errorMessage {
            Text(errorMessage)
                .foregroundStyle(.red)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else if viewModel.query.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            Text("Start typing to search")
                .foregroundStyle(.secondary)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else if viewModel.results.isEmpty {
            Text("No results")
                .foregroundStyle(.secondary)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else {
            List(viewModel.results) { result in
                VStack(alignment: .leading) {
                    Text(result.title)
                    Text(result.subtitle)
                        .font(.subheadline)
                        .foregroundStyle(.secondary)
                }
            }
        }
    }
}

import Foundation
import SwiftUI

enum AppTheme: String, CaseIterable, Identifiable {
    case system
    case light
    case dark

    var id: String { rawValue }

    var displayName: String {
        switch self {
        case .system: return "System"
        case .light: return "Light"
        case .dark: return "Dark"
        }
    }
}

final class SettingsStore: ObservableObject {
    @Published var displayName: String {
        didSet { saveIfNeeded(displayName, forKey: Keys.displayName) }
    }
    @Published var theme: AppTheme {
        didSet { saveIfNeeded(theme.rawValue, forKey: Keys.theme) }
    }
    @Published var notificationsEnabled: Bool {
        didSet { saveIfNeeded(notificationsEnabled, forKey: Keys.notificationsEnabled) }
    }
    @Published var refreshInterval: Double {
        didSet { saveIfNeeded(refreshInterval, forKey: Keys.refreshInterval) }
    }

    private enum Keys {
        static let displayName = "settings.displayName"
        static let theme = "settings.theme"
        static let notificationsEnabled = "settings.notificationsEnabled"
        static let refreshInterval = "settings.refreshInterval"
    }

    private let defaults: UserDefaults
    private var isSyncingFromExternalChange = false

    init(defaults: UserDefaults = .standard) {
        self.defaults = defaults
        self.displayName = defaults.string(forKey: Keys.displayName) ?? ""
        self.theme = AppTheme(rawValue: defaults.string(forKey: Keys.theme) ?? "") ?? .system
        self.notificationsEnabled = (defaults.object(forKey: Keys.notificationsEnabled) as? Bool) ?? true
        self.refreshInterval = (defaults.object(forKey: Keys.refreshInterval) as? Double) ?? 60

        NotificationCenter.default.addObserver(
            self,
            selector: #selector(handleExternalChange),
            name: UserDefaults.didChangeNotification,
            object: defaults
        )
    }

    deinit {
        NotificationCenter.default.removeObserver(self)
    }

    private func saveIfNeeded(_ value: Any, forKey key: String) {
        guard !isSyncingFromExternalChange else { return }
        defaults.set(value, forKey: key)
    }

    @objc private func handleExternalChange() {
        DispatchQueue.main.async { [weak self] in
            guard let self else { return }
            self.isSyncingFromExternalChange = true
            self.displayName = self.defaults.string(forKey: Keys.displayName) ?? self.displayName
            self.theme = AppTheme(rawValue: self.defaults.string(forKey: Keys.theme) ?? "") ?? self.theme
            self.notificationsEnabled = (self.defaults.object(forKey: Keys.notificationsEnabled) as? Bool) ?? self.notificationsEnabled
            self.refreshInterval = (self.defaults.object(forKey: Keys.refreshInterval) as? Double) ?? self.refreshInterval
            self.isSyncingFromExternalChange = false
        }
    }
}

struct SettingsScreen: View {
    @ObservedObject var store: SettingsStore

    var body: some View {
        Form {
            Section("Profile") {
                TextField("Display Name", text: $store.displayName)
            }

            Section("Appearance") {
                Picker("Theme", selection: $store.theme) {
                    ForEach(AppTheme.allCases) { theme in
                        Text(theme.displayName).tag(theme)
                    }
                }
            }

            Section("Notifications") {
                Toggle("Enable Notifications", isOn: $store.notificationsEnabled)
            }

            Section("Refresh") {
                Stepper(
                    "Refresh Interval: \(Int(store.refreshInterval))s",
                    value: $store.refreshInterval,
                    in: 5...300,
                    step: 5
                )
            }
        }
        .padding()
    }
}

import Combine
import Foundation
import SwiftUI

enum AppTheme: String, CaseIterable, Identifiable, Codable {
    case system
    case light
    case dark

    var id: String { rawValue }

    var displayName: String {
        switch self {
        case .system: return "System"
        case .light: return "Light"
        case .dark: return "Dark"
        }
    }
}

/// Persists settings to UserDefaults and stays in sync if they're changed elsewhere
/// (e.g. another window, or a sync mechanism writing directly to UserDefaults).
@MainActor
final class SettingsStore: ObservableObject {
    enum Keys {
        static let displayName = "settings.displayName"
        static let theme = "settings.theme"
        static let notificationsEnabled = "settings.notificationsEnabled"
        static let refreshInterval = "settings.refreshInterval"
    }

    static let defaultRefreshInterval: TimeInterval = 60

    @Published var displayName: String {
        didSet {
            guard !isApplyingExternalChange, oldValue != displayName else { return }
            defaults.set(displayName, forKey: Keys.displayName)
        }
    }

    @Published var theme: AppTheme {
        didSet {
            guard !isApplyingExternalChange, oldValue != theme else { return }
            defaults.set(theme.rawValue, forKey: Keys.theme)
        }
    }

    @Published var notificationsEnabled: Bool {
        didSet {
            guard !isApplyingExternalChange, oldValue != notificationsEnabled else { return }
            defaults.set(notificationsEnabled, forKey: Keys.notificationsEnabled)
        }
    }

    @Published var refreshInterval: TimeInterval {
        didSet {
            guard !isApplyingExternalChange, oldValue != refreshInterval else { return }
            defaults.set(refreshInterval, forKey: Keys.refreshInterval)
        }
    }

    private let defaults: UserDefaults
    // Guards against re-writing values we just loaded from a didChangeNotification,
    // which would otherwise re-post the notification and loop forever.
    private var isApplyingExternalChange = false
    private var cancellable: AnyCancellable?

    init(defaults: UserDefaults = .standard) {
        self.defaults = defaults

        displayName = defaults.string(forKey: Keys.displayName) ?? ""
        theme = AppTheme(rawValue: defaults.string(forKey: Keys.theme) ?? "") ?? .system
        notificationsEnabled = defaults.object(forKey: Keys.notificationsEnabled) != nil
            ? defaults.bool(forKey: Keys.notificationsEnabled)
            : true
        refreshInterval = defaults.object(forKey: Keys.refreshInterval) != nil
            ? defaults.double(forKey: Keys.refreshInterval)
            : Self.defaultRefreshInterval

        cancellable = NotificationCenter.default
            .publisher(for: UserDefaults.didChangeNotification, object: defaults)
            .sink { [weak self] _ in
                self?.reloadFromDefaults()
            }
    }

    private func reloadFromDefaults() {
        isApplyingExternalChange = true
        defer { isApplyingExternalChange = false }

        let newDisplayName = defaults.string(forKey: Keys.displayName) ?? ""
        if newDisplayName != displayName { displayName = newDisplayName }

        let newTheme = AppTheme(rawValue: defaults.string(forKey: Keys.theme) ?? "") ?? .system
        if newTheme != theme { theme = newTheme }

        let newNotificationsEnabled = defaults.object(forKey: Keys.notificationsEnabled) != nil
            ? defaults.bool(forKey: Keys.notificationsEnabled)
            : true
        if newNotificationsEnabled != notificationsEnabled { notificationsEnabled = newNotificationsEnabled }

        let newRefreshInterval = defaults.object(forKey: Keys.refreshInterval) != nil
            ? defaults.double(forKey: Keys.refreshInterval)
            : Self.defaultRefreshInterval
        if newRefreshInterval != refreshInterval { refreshInterval = newRefreshInterval }
    }
}

struct SettingsScreen: View {
    @ObservedObject var store: SettingsStore

    private let refreshIntervalOptions: [TimeInterval] = [15, 30, 60, 300, 900]

    var body: some View {
        Form {
            Section("Profile") {
                TextField("Display Name", text: $store.displayName)
            }

            Section("Appearance") {
                Picker("Theme", selection: $store.theme) {
                    ForEach(AppTheme.allCases) { theme in
                        Text(theme.displayName).tag(theme)
                    }
                }
            }

            Section("Notifications") {
                Toggle("Enable Notifications", isOn: $store.notificationsEnabled)
            }

            Section("Refresh") {
                Picker("Refresh Interval", selection: $store.refreshInterval) {
                    ForEach(refreshIntervalOptions, id: \.self) { interval in
                        Text(Self.label(for: interval)).tag(interval)
                    }
                }
            }
        }
        .navigationTitle("Settings")
    }

    private static func label(for interval: TimeInterval) -> String {
        if interval < 60 {
            return "\(Int(interval))s"
        } else {
            return "\(Int(interval / 60))m"
        }
    }
}

