/// Wraps `LegacyUploader`, exposing progress as an `AsyncStream` alongside
/// an `async throws` entry point for the upload itself.
final class Uploader {
    private let legacy = LegacyUploader()

    let progress: AsyncStream<Double>
    private let progressContinuation: AsyncStream<Double>.Continuation

    init() {
        var continuation: AsyncStream<Double>.Continuation!
        progress = AsyncStream { continuation = $0 }
        progressContinuation = continuation
    }

    func upload(file: URL) async throws {
        legacy.onProgress = { [progressContinuation] value in
            progressContinuation.yield(value)
        }
        try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
            legacy.onFinish = { [progressContinuation] error in
                if let error {
                    continuation.resume(throwing: error)
                } else {
                    continuation.resume()
                }
                progressContinuation.finish()
            }
            legacy.start(file: file)
        }
