private let logger = Logger(subsystem: "App", category: "ThumbnailGrid")

#if canImport(UIKit)
import UIKit
public typealias PlatformImage = UIImage
#elseif canImport(AppKit)
import AppKit
public typealias PlatformImage = NSImage
#endif

/// A downloaded thumbnail together with the moment it was fetched.
private final class CachedThumbnail {
    let image: PlatformImage
    let downloadDate: Date

    init(image: PlatformImage, downloadDate: Date) {
        self.image = image
        self.downloadDate = downloadDate
    }
}

/// Shared in-memory cache so thumbnails aren't re-downloaded when scrolled
/// out of view and back. `NSCache` is thread-safe, so this can be called
/// from any thread without extra synchronization.
private final class ThumbnailCache: @unchecked Sendable {
    static let shared = ThumbnailCache()

    private let cache = NSCache<NSURL, CachedThumbnail>()

    private init() {
        cache.countLimit = 500
    }

    func thumbnail(for url: URL) -> CachedThumbnail? {
        cache.object(forKey: url as NSURL)
    }

    func insert(_ thumbnail: CachedThumbnail, for url: URL) {
        cache.setObject(thumbnail, forKey: url as NSURL)
    }
}

private extension Image {
    init(platformImage: PlatformImage) {
        #if canImport(UIKit)
        self.init(uiImage: platformImage)
        #elseif canImport(AppKit)
        self.init(nsImage: platformImage)
        #endif
    }
}

/// A single grid cell: downloads (or reuses a cached copy of) the image at
/// `url`, showing a placeholder until it's available, plus a relative
/// timestamp of when it was downloaded.
private struct ThumbnailCell: View {
    let url: URL

    @State private var thumbnail: CachedThumbnail?

    var body: some View {
        VStack(spacing: 4) {
            ZStack {
                if let thumbnail {
                    Image(platformImage: thumbnail.image)
                        .resizable()
                        .aspectRatio(contentMode: .fill)
                } else {
                    Rectangle()
                        .fill(Color.gray.opacity(0.2))
                    ProgressView()
                }
            }
            .frame(width: 100, height: 100)
            .clipped()
            .cornerRadius(8)

            if let thumbnail {
                Text(thumbnail.downloadDate, format: .relative(presentation: .named))
                    .font(.caption)
                    .foregroundStyle(.secondary)
                    .lineLimit(1)
            } else {
                Text(" ")
                    .font(.caption)
            }
        }
        .task(id: url) {
            await load()
        }
    }

    private func load() async {
        if let cached = ThumbnailCache.shared.thumbnail(for: url) {
            thumbnail = cached
            return
        }

        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            guard let image = PlatformImage(data: data) else { return }
            let downloaded = CachedThumbnail(image: image, downloadDate: Date())
            ThumbnailCache.shared.insert(downloaded, for: url)
            thumbnail = downloaded
        } catch {
            // Leave the placeholder in place; a future scroll-back will retry.
            logger.error("Failed to load thumbnail \(url): \(error)")
        }
    }
}

/// A scrollable grid of photo thumbnails loaded from `urls`.
public struct ThumbnailGrid: View {
    private let urls: [URL]
    private let columns = [GridItem(.adaptive(minimum: 100), spacing: 8)]

    public init(urls: [URL]) {
        self.urls = urls
    }

    public var body: some View {
        ScrollView {
            LazyVGrid(columns: columns, spacing: 8) {
                ForEach(urls, id: \.self) { url in
                    ThumbnailCell(url: url)
                }
            }
            .padding(8)
        }
    }
}

import Foundation
import SwiftUI

struct ChatMessage: Codable, Identifiable, Equatable {
    let id: String
    let author: String
    let text: String
}

@MainActor
final class ChatConnection: ObservableObject {
    @Published private(set) var messages: [ChatMessage] = []
    @Published private(set) var isConnected = false

    private let url: URL
    private let session: URLSession
    private var task: URLSessionWebSocketTask?
    private var reconnectAttempt = 0
    private var reconnectTask: Task<Void, Never>?
    private var isStopped = false

    init(url: URL = URL(string: "wss://chat.example.com/room")!) {
        self.url = url
        self.session = URLSession(configuration: .default)
    }

    func start() {
        isStopped = false
        connect()
    }

    func stop() {
        isStopped = true
        reconnectTask?.cancel()
        task?.cancel(with: .goingAway, reason: nil)
        task = nil
        isConnected = false
    }

    func send(text: String) {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, let task else { return }

        let message = ChatMessage(id: UUID().uuidString, author: "me", text: trimmed)
        guard let data = try? JSONEncoder().encode(message),
              let json = String(data: data, encoding: .utf8) else { return }

        task.send(.string(json)) { [weak self] error in
            if error != nil {
                Task { @MainActor in self?.handleFailure() }
            }
        }

        messages.append(message)
    }

    private func connect() {
        let newTask = session.webSocketTask(with: url)
        task = newTask
        newTask.resume()
        isConnected = true
        reconnectAttempt = 0
        receiveNext()
    }

    private func receiveNext() {
        guard let task else { return }
        task.receive { [weak self] result in
            Task { @MainActor in
                guard let self, self.task === task else { return }
                switch result {
                case .success(let message):
                    self.handle(message)
                    self.receiveNext()
                case .failure:
                    self.handleFailure()
                }
            }
        }
    }

    private func handle(_ message: URLSessionWebSocketTask.Message) {
        let data: Data
        switch message {
        case .data(let raw):
            data = raw
        case .string(let raw):
            data = Data(raw.utf8)
        @unknown default:
            return
        }

        guard let decoded = try? JSONDecoder().decode(ChatMessage.self, from: data) else { return }
        messages.append(decoded)
    }

    private func handleFailure() {
        guard !isStopped, task != nil else { return }
        task = nil
        isConnected = false
        scheduleReconnect()
    }

    private func scheduleReconnect() {
        guard !isStopped else { return }
        reconnectAttempt += 1
        let delay = min(30.0, pow(2.0, Double(reconnectAttempt)))

        reconnectTask?.cancel()
        reconnectTask = Task { [weak self] in
            try? await Task.sleep(nanoseconds: UInt64(delay * 1_000_000_000))
            guard let self, !Task.isCancelled, !self.isStopped else { return }
            self.connect()
        }
    }
}

struct ChatScreen: View {
    @StateObject private var connection = ChatConnection()
    @State private var draft = ""

    var body: some View {
        VStack(spacing: 0) {
            ScrollViewReader { proxy in
                ScrollView {
                    LazyVStack(alignment: .leading, spacing: 8) {
                        ForEach(connection.messages) { message in
                            VStack(alignment: .leading, spacing: 2) {
                                Text(message.author)
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                                Text(message.text)
                            }
                            .id(message.id)
                            .frame(maxWidth: .infinity, alignment: .leading)
                        }
                    }
                    .padding()
                }
                .onChange(of: connection.messages) { newMessages in
                    guard let lastID = newMessages.last?.id else { return }
                    withAnimation {
                        proxy.scrollTo(lastID, anchor: .bottom)
                    }
                }
            }

            Divider()

            HStack {
                TextField("Message", text: $draft)
                    .textFieldStyle(.roundedBorder)
                    .onSubmit(sendDraft)
                Button("Send", action: sendDraft)
                    .disabled(draft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
            }
            .padding()
        }
        .onAppear { connection.start() }
        .onDisappear { connection.stop() }
    }

    private func sendDraft() {
        connection.send(text: draft)
        draft = ""
    }
}

import { useEffect, useMemo, useState } from "react";

interface User {
  id: string;
  name: string;
  email: string;
}

type SortField = "name" | "email";

const DEBOUNCE_MS = 300;

export function UserSearch() {
  const [query, setQuery] = useState("");
  const [debouncedQuery, setDebouncedQuery] = useState("");
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [sortField, setSortField] = useState<SortField>("name");

  useEffect(() => {
    const handle = setTimeout(() => setDebouncedQuery(query), DEBOUNCE_MS);
    return () => clearTimeout(handle);
  }, [query]);

  useEffect(() => {
    if (debouncedQuery.trim() === "") {
      setUsers([]);
      setError(null);
      setLoading(false);
      return;
    }

    const controller = new AbortController();
    setLoading(true);
    setError(null);

    fetch(`/api/users?q=${encodeURIComponent(debouncedQuery)}`, {
      signal: controller.signal,
    })
      .then((res) => {
        if (!res.ok) {
          throw new Error(`Request failed with status ${res.status}`);
        }
        return res.json() as Promise<User[]>;
      })
      .then((data) => {
        setUsers(data);
      })
      .catch((err: unknown) => {
        if (err instanceof DOMException && err.name === "AbortError") {
          return;
        }
        setError(err instanceof Error ? err.message : "Failed to fetch users");
      })
      .finally(() => {
        setLoading(false);
      });

    return () => controller.abort();
  }, [debouncedQuery]);

  const sortedUsers = useMemo(() => {
    return [...users].sort((a, b) => a[sortField].localeCompare(b[sortField]));
  }, [users, sortField]);

  return (
    <div>
      <input
        type="text"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search users..."
        aria-label="Search users"
      />

      <label>
        Sort by:{" "}
        <select
          value={sortField}
          onChange={(e) => setSortField(e.target.value as SortField)}
        >
          <option value="name">Name</option>
          <option value="email">Email</option>
        </select>
      </label>

      {loading && <p>Loading...</p>}
      {error && <p role="alert">Error: {error}</p>}
      {!loading && !error && debouncedQuery.trim() !== "" && (
        <p>{sortedUsers.length} result{sortedUsers.length === 1 ? "" : "s"}</p>
      )}

      <ul>
        {sortedUsers.map((user) => (
          <li key={user.id}>
            <strong>{user.name}</strong> ({user.email})
          </li>
        ))}
      </ul>
    </div>
  );
}

export default UserSearch;

import Foundation
import SwiftUI

struct ChatMessage: Identifiable, Codable, Equatable {
    let id: String
    let author: String
    let text: String
}

@MainActor
final class ChatViewModel: ObservableObject {
    @Published private(set) var messages: [ChatMessage] = []
    @Published var draft: String = ""

    private static let urlString = "wss://chat.example.com/room"
    private let session = URLSession(configuration: .default)
    private var webSocketTask: URLSessionWebSocketTask?
    private var reconnectDelay: TimeInterval = 1
    private let maxReconnectDelay: TimeInterval = 30
    private var isStopped = false

    func connect() {
        isStopped = false
        guard webSocketTask == nil, let url = URL(string: Self.urlString) else { return }
        let task = session.webSocketTask(with: url)
        webSocketTask = task
        task.resume()
        reconnectDelay = 1
        receiveNextMessage(on: task)
    }

    func disconnect() {
        isStopped = true
        webSocketTask?.cancel(with: .goingAway, reason: nil)
        webSocketTask = nil
    }

    func sendDraft() {
        let trimmed = draft.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, let task = webSocketTask else { return }
        let message = ChatMessage(id: UUID().uuidString, author: "me", text: trimmed)
        guard let data = try? JSONEncoder().encode(message) else { return }
        draft = ""
        task.send(.data(data)) { [weak self] error in
            guard error != nil else { return }
            Task { @MainActor in
                self?.handleDisconnect(of: task)
            }
        }
    }

    private func receiveNextMessage(on task: URLSessionWebSocketTask) {
        task.receive { [weak self] result in
            Task { @MainActor in
                guard let self else { return }
                switch result {
                case .success(let message):
                    self.handleIncoming(message)
                    self.receiveNextMessage(on: task)
                case .failure:
                    self.handleDisconnect(of: task)
                }
            }
        }
    }

    private func handleIncoming(_ message: URLSessionWebSocketTask.Message) {
        let data: Data
        switch message {
        case .data(let raw):
            data = raw
        case .string(let text):
            data = Data(text.utf8)
        @unknown default:
            return
        }
        guard let chatMessage = try? JSONDecoder().decode(ChatMessage.self, from: data) else { return }
        messages.append(chatMessage)
    }

    private func handleDisconnect(of task: URLSessionWebSocketTask) {
        guard webSocketTask === task else { return }
        webSocketTask = nil
        guard !isStopped else { return }
        let delay = reconnectDelay
        reconnectDelay = min(reconnectDelay * 2, maxReconnectDelay)
        Task { @MainActor in
            try? await Task.sleep(nanoseconds: UInt64(delay * 1_000_000_000))
            guard !self.isStopped else { return }
            self.connect()
        }
    }
}

struct ChatScreen: View {
    @StateObject private var viewModel = ChatViewModel()

    var body: some View {
        VStack(spacing: 0) {
            ScrollViewReader { proxy in
                ScrollView {
                    LazyVStack(alignment: .leading, spacing: 8) {
                        ForEach(viewModel.messages) { message in
                            VStack(alignment: .leading, spacing: 2) {
                                Text(message.author)
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                                Text(message.text)
                            }
                            .frame(maxWidth: .infinity, alignment: .leading)
                            .id(message.id)
                        }
                    }
                    .padding()
                }
                .onChange(of: viewModel.messages) { _ in
                    guard let lastID = viewModel.messages.last?.id else { return }
                    withAnimation {
                        proxy.scrollTo(lastID, anchor: .bottom)
                    }
                }
            }
            Divider()
            HStack {
                TextField("Message", text: $viewModel.draft)
                    .textFieldStyle(.roundedBorder)
                    .onSubmit { viewModel.sendDraft() }
                Button("Send") { viewModel.sendDraft() }
                    .disabled(viewModel.draft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
            }
            .padding()
        }
        .onAppear { viewModel.connect() }
        .onDisappear { viewModel.disconnect() }
    }
}

import { useEffect, useMemo, useState } from "react";

interface User {
  id: string;
  name: string;
  email: string;
}

type SortField = "name" | "email";

const DEBOUNCE_MS = 300;

function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    typeof candidate.name === "string" &&
    typeof candidate.email === "string"
  );
}

function parseUsers(data: unknown): User[] {
  if (!Array.isArray(data) || !data.every(isUser)) {
    throw new Error("Received malformed user data from server");
  }
  return data;
}

