          placeholder="Add a new todo"
        />
        <button type="submit">Add</button>
      </form>

      <div>
        <button onClick={() => setFilter("all")} disabled={filter === "all"}>
          All
        </button>
        <button
          onClick={() => setFilter("active")}
          disabled={filter === "active"}
        >
          Active
        </button>
        <button
          onClick={() => setFilter("done")}
          disabled={filter === "done"}
        >
          Done
        </button>
      </div>

      <p>{remainingCount} item(s) remaining</p>

      <ul>
        {visibleTodos.map(({ todo, index }) => (
          <li key={todo.id}>
            <input
              type="checkbox"
              checked={todo.done}
              onChange={() => toggleDone(todo.id)}
            />

            {editingId === todo.id ? (
              <>
                <input
                  type="text"
                  value={editingText}
                  onChange={(e) => setEditingText(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") commitEdit();
                    if (e.key === "Escape") cancelEdit();
                  }}
                  autoFocus
                />
                <button onClick={commitEdit}>Save</button>
                <button onClick={cancelEdit}>Cancel</button>
              </>
            ) : (
              <>
                <span
                  style={{
                    textDecoration: todo.done ? "line-through" : "none",
                  }}
                >
                  {todo.text}
                </span>
                <button onClick={() => startEdit(todo)}>Edit</button>
              </>
            )}

            <button onClick={() => moveUp(index)} disabled={index === 0}>
              ↑
            </button>
            <button
              onClick={() => moveDown(index)}
              disabled={index === todos.length - 1}
            >
              ↓
            </button>
            <button onClick={() => deleteTodo(todo.id)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useEffect, useState } from "react";
import type { User } from "./ProfileEditor";

export interface UseUserProfilesResult {
  profiles: Record<string, User>;
  isLoading: boolean;
  error: Error | null;
}

export function useUserProfiles(ids: string[]): UseUserProfilesResult {
  const [profiles, setProfiles] = useState<Record<string, User>>({});
  const [isLoading, setIsLoading] = useState(ids.length > 0);
  const [error, setError] = useState<Error | null>(null);

  const key = ids.join(",");

  useEffect(() => {
    if (ids.length === 0) {
      setProfiles({});
      setIsLoading(false);
      setError(null);
      return;
    }

    let cancelled = false;
    setIsLoading(true);
    setError(null);

    Promise.all(
      ids.map(async (id) => {
        const response = await fetch(`/api/users/${id}`);
        if (!response.ok) {
          throw new Error(`Failed to load user ${id}: ${response.status}`);
        }
        const user = (await response.json()) as User;
        return [id, user] as const;
      })
    )
      .then((entries) => {
        if (cancelled) return;
        setProfiles(Object.fromEntries(entries));
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(err instanceof Error ? err : new Error(String(err)));
      })
      .finally(() => {
        if (cancelled) return;
        setIsLoading(false);
      });

    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key]);

  return { profiles, isLoading, error };
}

import { useState } from "react";

export interface User {
  id: string;
  displayName: string;
  bio: string;
  avatarUrl: string;
}

export interface ProfileEditorProps {
  user: User;
