      </label>

      <p>{hasChanges ? "You have unsaved changes." : "No unsaved changes."}</p>

      {error && <p role="alert">{error}</p>}

      <button type="submit" disabled={!hasChanges || isSaving}>
        {isSaving ? "Saving..." : "Save"}
      </button>
      <button type="button" onClick={handleReset} disabled={!hasChanges || isSaving}>
        Reset
      </button>
    </form>
  );
}

import SwiftUI

struct SearchResult: Decodable, Identifiable, Hashable {
    let id: String
    let title: String
    let subtitle: String
}

private struct SearchResponse: Decodable {
    let results: [SearchResult]
}

enum SearchError: LocalizedError {
    case invalidURL
    case invalidResponse

    var errorDescription: String? {
        switch self {
        case .invalidURL:
            return "Invalid search URL."
        case .invalidResponse:
            return "The server returned an invalid response."
        }
    }
}

@MainActor
final class SearchViewModel: ObservableObject {
    @Published var query: String = ""
    @Published private(set) var results: [SearchResult] = []
    @Published private(set) var isLoading = false
    @Published private(set) var errorMessage: String?

    private let session: URLSession
    private let debounceNanoseconds: UInt64
    private static let baseURLString = "https://api.example.com/search"

    init(session: URLSession = .shared, debounceNanoseconds: UInt64 = 300_000_000) {
        self.session = session
        self.debounceNanoseconds = debounceNanoseconds
    }

    /// Debounces on the caller's task lifetime: run this from a `.task(id: query)`
    /// modifier so SwiftUI cancels the in-flight sleep/fetch whenever `query` changes.
    func search(for query: String) async {
        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            results = []
            errorMessage = nil
            isLoading = false
            return
        }

        do {
            try await Task.sleep(nanoseconds: debounceNanoseconds)
        } catch {
            return
        }
        guard !Task.isCancelled else { return }

        isLoading = true
        errorMessage = nil

        do {
            let fetched = try await performSearch(query: trimmed)
            guard !Task.isCancelled else { return }
            results = fetched
            isLoading = false
        } catch is CancellationError {
            return
        } catch {
            guard !Task.isCancelled else { return }
            results = []
            errorMessage = error.localizedDescription
            isLoading = false
        }
    }

    private func performSearch(query: String) async throws -> [SearchResult] {
        var components = URLComponents(string: Self.baseURLString)
        components?.queryItems = [URLQueryItem(name: "q", value: query)]
        guard let url = components?.url else {
            throw SearchError.invalidURL
        }

        let (data, response) = try await session.data(from: url)
        guard let httpResponse = response as? HTTPURLResponse,
              (200..<300).contains(httpResponse.statusCode) else {
            throw SearchError.invalidResponse
        }

        return try JSONDecoder().decode(SearchResponse.self, from: data).results
    }
}

struct SearchScreen: View {
    @StateObject private var viewModel = SearchViewModel()

    var body: some View {
        NavigationStack {
            content
                .navigationTitle("Search")
                .searchable(text: $viewModel.query, prompt: "Search")
        }
        .task(id: viewModel.query) {
            await viewModel.search(for: viewModel.query)
        }
    }

    @ViewBuilder
    private var content: some View {
        if viewModel.isLoading {
            ProgressView("Searching…")
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else if let errorMessage = viewModel.errorMessage {
            VStack(spacing: 8) {
                Text("Something went wrong")
                    .font(.headline)
                Text(errorMessage)
                    .font(.subheadline)
                    .foregroundStyle(.secondary)
                    .multilineTextAlignment(.center)
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .padding()
        } else if viewModel.query.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            Text("Start typing to search")
                .foregroundStyle(.secondary)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else if viewModel.results.isEmpty {
            Text("No results for \"\(viewModel.query)\"")
                .foregroundStyle(.secondary)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        } else {
            List(viewModel.results) { result in
                VStack(alignment: .leading, spacing: 2) {
                    Text(result.title)
                        .font(.headline)
                    Text(result.subtitle)
                        .font(.subheadline)
                        .foregroundStyle(.secondary)
                }
            }
        }
    }
}

