struct Lap: Identifiable {
    let id = UUID()
    let number: Int
    let splitTime: TimeInterval
    let totalTime: TimeInterval
}

@MainActor
final class StopwatchViewModel: ObservableObject {
    @Published private(set) var elapsedTime: TimeInterval = 0
    @Published private(set) var laps: [Lap] = []
    @Published private(set) var isRunning = false

    private var timer: Timer?
    private var startDate: Date?
    private var accumulatedTime: TimeInterval = 0

    func start() {
        guard !isRunning else { return }
        isRunning = true
        startDate = Date()
        timer = Timer.scheduledTimer(withTimeInterval: 0.01, repeats: true) { [weak self] _ in
            guard let self else { return }
            Task { @MainActor in
                self.tick()
            }
        }
    }

    func stop() {
        guard isRunning else { return }
        isRunning = false
        timer?.invalidate()
        timer = nil
        accumulatedTime = elapsedTime
        startDate = nil
    }

    func reset() {
        stop()
        elapsedTime = 0
        accumulatedTime = 0
        laps = []
    }

    func lap() {
        guard isRunning else { return }
        let previousTotal = laps.last?.totalTime ?? 0
        let split = elapsedTime - previousTotal
        laps.append(Lap(number: laps.count + 1, splitTime: split, totalTime: elapsedTime))
    }

    private func tick() {
        guard let startDate else { return }
        elapsedTime = accumulatedTime + Date().timeIntervalSince(startDate)
    }

    static func formatted(_ time: TimeInterval) -> String {
        let minutes = Int(time) / 60
        let seconds = Int(time) % 60
        let centiseconds = Int((time.truncatingRemainder(dividingBy: 1)) * 100)
        return String(format: "%02d:%02d.%02d", minutes, seconds, centiseconds)
    }
}

struct StopwatchView: View {
    @StateObject private var viewModel = StopwatchViewModel()

    var body: some View {
        VStack(spacing: 24) {
            Text(StopwatchViewModel.formatted(viewModel.elapsedTime))
                .font(.system(size: 54, weight: .medium, design: .monospaced))
                .monospacedDigit()

            HStack(spacing: 16) {
                Button(viewModel.isRunning ? "Stop" : "Start") {
                    viewModel.isRunning ? viewModel.stop() : viewModel.start()
                }
                .keyboardShortcut(.defaultAction)

                Button("Lap") {
                    viewModel.lap()
                }
                .disabled(!viewModel.isRunning)

                Button("Reset") {
                    viewModel.reset()
                }
                .disabled(viewModel.isRunning && viewModel.elapsedTime == 0)
            }

            List(viewModel.laps.reversed()) { lap in
                HStack {
                    Text("Lap \(lap.number)")
                        .foregroundStyle(.secondary)
                    Spacer()
                    Text(StopwatchViewModel.formatted(lap.splitTime))
                        .monospacedDigit()
                    Spacer()
                    Text(StopwatchViewModel.formatted(lap.totalTime))
                        .monospacedDigit()
                }
            }
        }
        .padding()
        .frame(minWidth: 320, minHeight: 400)
    }
}

import Foundation
import SwiftUI

struct SearchResult: Decodable, Identifiable, Hashable {
    let id: String
    let title: String
    let subtitle: String
}

@MainActor
final class SearchViewModel: ObservableObject {
    @Published var query: String = "" {
        didSet { scheduleSearch() }
    }
    @Published private(set) var results: [SearchResult] = []
    @Published private(set) var isLoading: Bool = false
    @Published private(set) var errorMessage: String?

    private let session: URLSession
    private let debounceInterval: Duration
    private var searchTask: Task<Void, Never>?

    init(session: URLSession = .shared, debounceInterval: Duration = .milliseconds(300)) {
        self.session = session
        self.debounceInterval = debounceInterval
    }

    private func scheduleSearch() {
        searchTask?.cancel()

        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            results = []
            errorMessage = nil
            isLoading = false
            return
        }

        searchTask = Task { [debounceInterval] in
            do {
                try await Task.sleep(for: debounceInterval)
            } catch {
                return
            }
            guard !Task.isCancelled else { return }
            await self.performSearch(for: trimmed)
        }
    }

    private func performSearch(for term: String) async {
        isLoading = true
        errorMessage = nil

        var components = URLComponents(string: "https://api.example.com/search")
        components?.queryItems = [URLQueryItem(name: "q", value: term)]

        guard let url = components?.url else {
            isLoading = false
            errorMessage = "Invalid search query."
            return
        }

        do {
            let (data, response) = try await session.data(from: url)
            guard !Task.isCancelled else { return }

            if let httpResponse = response as? HTTPURLResponse,
               !(200...299).contains(httpResponse.statusCode) {
                throw URLError(.badServerResponse)
            }

            let decoded = try JSONDecoder().decode([SearchResult].self, from: data)
            guard !Task.isCancelled else { return }

            results = decoded
            isLoading = false
        } catch is CancellationError {
            // A newer search superseded this one; leave state untouched.
        } catch {
            guard !Task.isCancelled else { return }
            results = []
            isLoading = false
            errorMessage = error.localizedDescription
        }
    }
}

struct SearchScreen: View {
    @StateObject private var viewModel = SearchViewModel()

    var body: some View {
        VStack(spacing: 0) {
            TextField("Search", text: $viewModel.query)
                .textFieldStyle(.roundedBorder)
                .padding()

            if let errorMessage = viewModel.errorMessage {
                Text(errorMessage)
                    .foregroundStyle(.red)
                    .padding(.horizontal)
                    .padding(.bottom)
            }

            if viewModel.isLoading {
                Spacer()
                ProgressView()
                Spacer()
            } else if viewModel.results.isEmpty {
                Spacer()
                Text(viewModel.query.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                     ? "Start typing to search."
                     : "No results.")
                    .foregroundStyle(.secondary)
                Spacer()
            } else {
                List(viewModel.results) { result in
                    VStack(alignment: .leading) {
                        Text(result.title)
                            .font(.headline)
                        Text(result.subtitle)
                            .font(.subheadline)
                            .foregroundStyle(.secondary)
                    }
                }
            }
        }
    }
}

