@MainActor
final class StopwatchViewModel: ObservableObject {
    @Published private(set) var elapsed: TimeInterval = 0
    @Published private(set) var laps: [TimeInterval] = []
    @Published private(set) var isRunning = false

    private var timer: Timer?
    private var startDate: Date?
    private var accumulated: TimeInterval = 0

    func start() {
        guard !isRunning else { return }
        isRunning = true
        startDate = Date()
        timer = Timer.scheduledTimer(withTimeInterval: 0.01, repeats: true) { [weak self] _ in
            Task { @MainActor in self?.tick() }
        }
    }

    func stop() {
        guard isRunning else { return }
        isRunning = false
        timer?.invalidate()
        timer = nil
        if let startDate {
            accumulated += Date().timeIntervalSince(startDate)
        }
        startDate = nil
        elapsed = accumulated
    }

    func reset() {
        stop()
        accumulated = 0
        elapsed = 0
        laps = []
    }

    func lap() {
        guard isRunning else { return }
        laps.append(elapsed)
    }

    private func tick() {
        guard let startDate else { return }
        elapsed = accumulated + Date().timeIntervalSince(startDate)
    }

    static func format(_ time: TimeInterval) -> String {
        let minutes = Int(time) / 60
        let seconds = Int(time) % 60
        let hundredths = Int((time - time.rounded(.down)) * 100)
        return String(format: "%02d:%02d.%02d", minutes, seconds, hundredths)
    }
}

struct StopwatchView: View {
    @StateObject private var viewModel = StopwatchViewModel()

    var body: some View {
        VStack(spacing: 24) {
            Text(StopwatchViewModel.format(viewModel.elapsed))
                .font(.system(size: 56, weight: .medium, design: .monospaced))
                .monospacedDigit()

            HStack(spacing: 16) {
                Button(viewModel.isRunning ? "Stop" : "Start") {
                    if viewModel.isRunning {
                        viewModel.stop()
                    } else {
                        viewModel.start()
                    }
                }
                Button("Lap") { viewModel.lap() }
                    .disabled(!viewModel.isRunning)
                Button("Reset") { viewModel.reset() }
                    .disabled(viewModel.isRunning)
            }
            .buttonStyle(.bordered)

            List {
                ForEach(lapRows) { row in
                    HStack {
                        Text("Lap \(row.number)")
                        Spacer()
                        Text(StopwatchViewModel.format(row.split))
                            .foregroundStyle(.secondary)
                        Text(StopwatchViewModel.format(row.total))
                            .monospacedDigit()
                    }
                }
            }
        }
        .padding()
        .frame(minWidth: 320, minHeight: 400)
    }

    private struct LapRow: Identifiable {
        let id: Int
        let number: Int
        let split: TimeInterval
        let total: TimeInterval
    }

    private var lapRows: [LapRow] {
        var previous: TimeInterval = 0
        var rows: [LapRow] = []
        for (index, total) in viewModel.laps.enumerated() {
            rows.append(LapRow(id: index, number: index + 1, split: total - previous, total: total))
            previous = total
        }
        return rows.reversed()
    }
}

