final class SettingsStore: ObservableObject {
    private enum Keys {
        static let displayName = "settings.displayName"
        static let theme = "settings.theme"
        static let notificationsEnabled = "settings.notificationsEnabled"
        static let refreshInterval = "settings.refreshInterval"
    }

    static let defaultRefreshInterval: TimeInterval = 60

    @Published var displayName: String {
        didSet { writeIfNeeded(displayName, forKey: Keys.displayName, oldValue: oldValue) }
    }

    @Published var theme: Theme {
        didSet { writeIfNeeded(theme.rawValue, forKey: Keys.theme, oldValue: oldValue.rawValue) }
    }

    @Published var notificationsEnabled: Bool {
        didSet { writeIfNeeded(notificationsEnabled, forKey: Keys.notificationsEnabled, oldValue: oldValue) }
    }

    @Published var refreshInterval: TimeInterval {
        didSet { writeIfNeeded(refreshInterval, forKey: Keys.refreshInterval, oldValue: oldValue) }
    }

    private let defaults: UserDefaults
    private var isApplyingExternalChange = false
    private var observer: NSObjectProtocol?

    init(defaults: UserDefaults = .standard) {
        self.defaults = defaults
        self.displayName = defaults.string(forKey: Keys.displayName) ?? ""
        self.theme = Theme(rawValue: defaults.string(forKey: Keys.theme) ?? "") ?? .system
        self.notificationsEnabled = defaults.object(forKey: Keys.notificationsEnabled) as? Bool ?? true
        self.refreshInterval = defaults.object(forKey: Keys.refreshInterval) as? TimeInterval ?? Self.defaultRefreshInterval

        observer = NotificationCenter.default.addObserver(
            forName: UserDefaults.didChangeNotification,
            object: defaults,
            queue: .main
        ) { [weak self] _ in
            self?.reloadFromDefaults()
        }
    }

    deinit {
        if let observer {
            NotificationCenter.default.removeObserver(observer)
        }
    }

    private func reloadFromDefaults() {
        isApplyingExternalChange = true
        defer { isApplyingExternalChange = false }

        let newDisplayName = defaults.string(forKey: Keys.displayName) ?? ""
        if newDisplayName != displayName {
            displayName = newDisplayName
        }

        let newTheme = Theme(rawValue: defaults.string(forKey: Keys.theme) ?? "") ?? .system
        if newTheme != theme {
            theme = newTheme
        }

        let newNotificationsEnabled = defaults.object(forKey: Keys.notificationsEnabled) as? Bool ?? true
        if newNotificationsEnabled != notificationsEnabled {
            notificationsEnabled = newNotificationsEnabled
        }

        let newRefreshInterval = defaults.object(forKey: Keys.refreshInterval) as? TimeInterval ?? Self.defaultRefreshInterval
        if newRefreshInterval != refreshInterval {
            refreshInterval = newRefreshInterval
        }
    }

    private func writeIfNeeded<T: Equatable>(_ value: T, forKey key: String, oldValue: T) {
        guard !isApplyingExternalChange, value != oldValue else { return }
        defaults.set(value, forKey: key)
    }
}

