#if canImport(UIKit)
import UIKit
typealias PlatformImage = UIImage
#elseif canImport(AppKit)
import AppKit
typealias PlatformImage = NSImage
#endif

private extension Image {
    init(platformImage: PlatformImage) {
        #if canImport(UIKit)
        self.init(uiImage: platformImage)
        #elseif canImport(AppKit)
        self.init(nsImage: platformImage)
        #endif
    }
}

/// A thumbnail plus the moment it was fetched, so we can show "downloaded 3 minutes ago".
struct CachedThumbnail {
    let image: PlatformImage
    let downloadDate: Date
}

/// Shared in-memory cache so scrolling a thumbnail back into view reuses the
/// already-downloaded image instead of re-fetching it.
actor ThumbnailCache {
    static let shared = ThumbnailCache()

    private var entries: [URL: CachedThumbnail] = [:]
    private var inFlight: [URL: Task<CachedThumbnail, Error>] = [:]

    func thumbnail(for url: URL) async throws -> CachedThumbnail {
        if let cached = entries[url] {
            return cached
        }
        // Coalesce concurrent requests for the same URL (e.g. rapid scroll back and forth)
        // so we only download it once.
        if let existing = inFlight[url] {
            return try await existing.value
        }

        let task = Task<CachedThumbnail, Error> {
            let (data, _) = try await URLSession.shared.data(from: url)
            guard let image = PlatformImage(data: data) else {
                throw URLError(.cannotDecodeContentData)
            }
            return CachedThumbnail(image: image, downloadDate: Date())
        }
        inFlight[url] = task

        do {
            let result = try await task.value
            entries[url] = result
            inFlight[url] = nil
            return result
        } catch {
            inFlight[url] = nil
            throw error
        }
    }
}

private let relativeDateFormatter: RelativeDateTimeFormatter = {
    let formatter = RelativeDateTimeFormatter()
    formatter.unitsStyle = .full
    return formatter
}()

struct ThumbnailView: View {
    let url: URL

    @State private var thumbnail: CachedThumbnail?
    @State private var failed = false

    var body: some View {
        VStack(spacing: 4) {
            ZStack {
                Rectangle()
                    .fill(Color.secondary.opacity(0.2))
                if let thumbnail {
                    Image(platformImage: thumbnail.image)
                        .resizable()
                        .aspectRatio(contentMode: .fill)
                } else if failed {
                    Image(systemName: "exclamationmark.triangle")
                        .foregroundColor(.secondary)
                } else {
                    ProgressView()
                }
            }
            .frame(width: 100, height: 100)
            .clipShape(RoundedRectangle(cornerRadius: 8))

            if let thumbnail {
                Text(relativeDateFormatter.localizedString(for: thumbnail.downloadDate, relativeTo: Date()))
                    .font(.caption2)
                    .foregroundColor(.secondary)
                    .lineLimit(1)
            }
        }
        .task(id: url) {
            await load()
        }
    }

    private func load() async {
        failed = false
        do {
            thumbnail = try await ThumbnailCache.shared.thumbnail(for: url)
        } catch {
            if !Task.isCancelled {
                failed = true
            }
        }
    }
}

