    let urls: [URL]

    private let columns = [GridItem(.adaptive(minimum: 100), spacing: 8)]

    var body: some View {
        ScrollView {
            LazyVGrid(columns: columns, spacing: 8) {
                ForEach(urls, id: \.self) { url in
                    ThumbnailView(url: url)
                }
            }
            .padding(8)
        }
    }
}

