    private let legacy = LegacyGeocoder()

    func geocode(_ address: String) async throws -> (Double, Double) {
        try await withCheckedThrowingContinuation { continuation in
            legacy.geocode(address) { result in
                continuation.resume(with: result)
            }
        }
    }
}

final class UploaderBridge {
    private let legacy = LegacyUploader()
    private let progressContinuation: AsyncStream<Double>.Continuation
    let progress: AsyncStream<Double>

    init() {
        var continuation: AsyncStream<Double>.Continuation!
        self.progress = AsyncStream { continuation = $0 }
        self.progressContinuation = continuation
        legacy.onProgress = { [progressContinuation] value in
            progressContinuation.yield(value)
        }
    }

    func upload(file: URL) async throws {
        try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
            legacy.onFinish = { [progressContinuation] error in
                progressContinuation.finish()
                if let error {
                    continuation.resume(throwing: error)
                } else {
                    continuation.resume(returning: ())
                }
            }
            legacy.start(file: file)
        }
    }
}

import Foundation

// MARK: - Legacy callback-based SDK (stubs)

enum LegacyGeocoderError: Error {
    case invalidAddress
}

final class LegacyGeocoder {
    func geocode(_ address: String, completion: @escaping (Result<(Double, Double), Error>) -> Void) {
        DispatchQueue.global().asyncAfter(deadline: .now() + 0.1) {
            guard !address.isEmpty else {
                completion(.failure(LegacyGeocoderError.invalidAddress))
                return
            }
            completion(.success((37.7749, -122.4194)))
        }
    }
}

final class LegacyUploader {
    var onProgress: ((Double) -> Void)?
    var onFinish: ((Error?) -> Void)?

    func start(file: URL) {
        DispatchQueue.global().async {
            for step in 1...10 {
                Thread.sleep(forTimeInterval: 0.01)
                self.onProgress?(Double(step) / 10.0)
            }
            self.onFinish?(nil)
        }
    }
}

// MARK: - Modern async/await wrappers

func geocode(_ address: String) async throws -> (Double, Double) {
    let geocoder = LegacyGeocoder()
    return try await withCheckedThrowingContinuation { continuation in
        geocoder.geocode(address) { result in
            continuation.resume(with: result)
        }
    }
}

final class Uploader {
    private let legacyUploader = LegacyUploader()
    let progress: AsyncStream<Double>
    private let progressContinuation: AsyncStream<Double>.Continuation

    init() {
        var continuation: AsyncStream<Double>.Continuation!
        self.progress = AsyncStream<Double> { continuation = $0 }
        self.progressContinuation = continuation
    }

    func upload(file: URL) async throws {
        try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
            legacyUploader.onProgress = { [progressContinuation] value in
                progressContinuation.yield(value)
            }
            legacyUploader.onFinish = { [progressContinuation] error in
                progressContinuation.finish()
                if let error {
                    continuation.resume(throwing: error)
                } else {
                    continuation.resume()
                }
            }
            legacyUploader.start(file: file)
        }
    }
}

import SwiftUI

#if canImport(UIKit)
import UIKit
public typealias PlatformImage = UIImage
#elseif canImport(AppKit)
import AppKit
public typealias PlatformImage = NSImage
#endif

/// A downloaded thumbnail plus the moment it was fetched, so re-displaying
/// a cached thumbnail keeps showing its original download time.
public struct CachedThumbnail {
    public let image: PlatformImage
    public let downloadDate: Date
}

private final class ThumbnailCacheEntry {
    let value: CachedThumbnail
    init(value: CachedThumbnail) { self.value = value }
}

/// Shared in-memory cache so scrolling a thumbnail back into view reuses the
/// already-downloaded image instead of re-fetching it.
public actor ThumbnailCache {
    public static let shared = ThumbnailCache()

    private let cache = NSCache<NSURL, ThumbnailCacheEntry>()

    private init() {}

    public func entry(for url: URL) -> CachedThumbnail? {
        cache.object(forKey: url as NSURL)?.value
    }

    public func store(_ thumbnail: CachedThumbnail, for url: URL) {
        cache.setObject(ThumbnailCacheEntry(value: thumbnail), forKey: url as NSURL)
    }
}

private extension Image {
    init(platformImage: PlatformImage) {
        #if canImport(UIKit)
        self.init(uiImage: platformImage)
        #elseif canImport(AppKit)
        self.init(nsImage: platformImage)
        #endif
    }
}

private let relativeDateFormatter: RelativeDateTimeFormatter = {
    let formatter = RelativeDateTimeFormatter()
    formatter.unitsStyle = .full
    return formatter
}()

private struct ThumbnailCell: View {
    let url: URL

    @State private var thumbnail: CachedThumbnail?
    @State private var failed = false

    var body: some View {
        VStack(spacing: 4) {
            ZStack {
                if let thumbnail {
                    Image(platformImage: thumbnail.image)
                        .resizable()
                        .scaledToFill()
                } else if failed {
                    Image(systemName: "exclamationmark.triangle")
                        .foregroundStyle(.secondary)
                } else {
                    ProgressView()
                }
            }
            .frame(width: 100, height: 100)
            .background(Color.gray.opacity(0.2))
            .clipShape(RoundedRectangle(cornerRadius: 8))

            if let thumbnail {
                Text(relativeDateFormatter.localizedString(for: thumbnail.downloadDate, relativeTo: Date()))
                    .font(.caption2)
                    .foregroundStyle(.secondary)
            }
        }
        .task(id: url) {
            await load()
        }
    }

    private func load() async {
        if let cached = await ThumbnailCache.shared.entry(for: url) {
            thumbnail = cached
            return
        }
        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            guard let image = PlatformImage(data: data) else {
                failed = true
                return
            }
            let cached = CachedThumbnail(image: image, downloadDate: Date())
            await ThumbnailCache.shared.store(cached, for: url)
            thumbnail = cached
        } catch {
            failed = true
        }
    }
}

/// A scrollable grid of photo thumbnails downloaded from `urls`. Each cell
/// shows a placeholder while loading, then the image and a relative label
/// for when it was downloaded. Downloaded images are kept in
/// `ThumbnailCache.shared` so scrolling back doesn't re-download them.
public struct ThumbnailGrid: View {
    private let urls: [URL]
    private let columns: [GridItem]

    public init(urls: [URL], columnCount: Int = 3) {
        self.urls = urls
        self.columns = Array(repeating: GridItem(.flexible(), spacing: 8), count: columnCount)
    }

    public var body: some View {
        ScrollView {
            LazyVGrid(columns: columns, spacing: 8) {
                ForEach(urls, id: \.self) { url in
                    ThumbnailCell(url: url)
                }
            }
            .padding(8)
        }
    }
}

import SwiftUI
import Foundation

struct ChatMessage: Codable, Identifiable, Equatable {
    let id: String
    let author: String
    let text: String
}

@MainActor
final class ChatViewModel: NSObject, ObservableObject {
    @Published var messages: [ChatMessage] = []
    @Published var draft: String = ""

    private let url: URL
    private let session: URLSession
    private var webSocketTask: URLSessionWebSocketTask?
    private var reconnectDelay: TimeInterval = 1
    private let maxReconnectDelay: TimeInterval = 30
    private var isStopped = false

    init(url: URL = URL(string: "wss://chat.example.com/room")!) {
        self.url = url
        self.session = URLSession(configuration: .default)
        super.init()
        connect()
    }

    func connect() {
        let task = session.webSocketTask(with: url)
        webSocketTask = task
        task.resume()
        reconnectDelay = 1
        listen(on: task)
    }

    func send() {
        let trimmed = draft.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, let task = webSocketTask else { return }

        let outgoing = ChatMessage(id: UUID().uuidString, author: "me", text: trimmed)
        guard let data = try? JSONEncoder().encode(outgoing) else { return }

        task.send(.data(data)) { [weak self] error in
            guard error != nil else { return }
            Task { @MainActor in
                self?.scheduleReconnect()
            }
        }
        draft = ""
    }

    func stop() {
        isStopped = true
        webSocketTask?.cancel(with: .goingAway, reason: nil)
    }

    private func listen(on task: URLSessionWebSocketTask) {
        task.receive { [weak self] result in
            Task { @MainActor in
                guard let self, self.webSocketTask === task else { return }
                switch result {
                case .success(let message):
                    self.handle(message)
                    self.listen(on: task)
                case .failure:
                    self.scheduleReconnect()
                }
            }
        }
    }

    private func handle(_ message: URLSessionWebSocketTask.Message) {
        let data: Data?
        switch message {
        case .data(let raw):
            data = raw
        case .string(let text):
            data = text.data(using: .utf8)
        @unknown default:
            data = nil
        }
        guard let data, let chatMessage = try? JSONDecoder().decode(ChatMessage.self, from: data) else { return }
        messages.append(chatMessage)
    }

    private func scheduleReconnect() {
        guard !isStopped else { return }
        webSocketTask = nil
        let delay = reconnectDelay
        reconnectDelay = min(reconnectDelay * 2, maxReconnectDelay)
        Task { @MainActor in
            try? await Task.sleep(nanoseconds: UInt64(delay * 1_000_000_000))
            guard !self.isStopped else { return }
            self.connect()
        }
    }
}

struct ChatScreen: View {
    @StateObject private var viewModel = ChatViewModel()

    var body: some View {
        VStack(spacing: 0) {
            ScrollViewReader { proxy in
                ScrollView {
                    LazyVStack(alignment: .leading, spacing: 8) {
                        ForEach(viewModel.messages) { message in
                            VStack(alignment: .leading, spacing: 2) {
                                Text(message.author)
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                                Text(message.text)
                            }
                            .id(message.id)
                            .padding(.horizontal)
                        }
                    }
                    .padding(.vertical, 8)
                }
                .onChange(of: viewModel.messages) { _ in
                    scrollToBottom(proxy: proxy)
                }
                .onAppear {
                    scrollToBottom(proxy: proxy)
                }
            }

            Divider()

            HStack {
                TextField("Message", text: $viewModel.draft)
                    .textFieldStyle(.roundedBorder)
                    .onSubmit { viewModel.send() }
                Button("Send") { viewModel.send() }
                    .disabled(viewModel.draft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
            }
            .padding()
        }
        .onDisappear { viewModel.stop() }
    }

    private func scrollToBottom(proxy: ScrollViewProxy) {
        guard let lastId = viewModel.messages.last?.id else { return }
        withAnimation {
            proxy.scrollTo(lastId, anchor: .bottom)
        }
    }
}

import Foundation
import SwiftUI

struct ChatMessage: Codable, Identifiable, Equatable {
    let id: String
    let author: String
    let text: String
}

@MainActor
final class ChatConnection: NSObject, ObservableObject {
    @Published private(set) var messages: [ChatMessage] = []

    private let url: URL = {
        guard let url = URL(string: "wss://chat.example.com/room") else {
            preconditionFailure("Invalid chat URL")
        }
        return url
    }()
    private let session: URLSession
    private var task: URLSessionWebSocketTask?
    private let reconnectDelay: UInt64 = 3_000_000_000

    override init() {
        self.session = URLSession(configuration: .default)
        super.init()
    }

    func connect() {
        guard task == nil else { return }
        let task = session.webSocketTask(with: url)
        self.task = task
        task.resume()
        listen()
    }

    private func listen() {
        guard let task else { return }
        task.receive { [weak self] result in
            guard let self else { return }
            Task { @MainActor in
                switch result {
                case .success(let message):
                    self.handle(message)
                    self.listen()
                case .failure:
                    self.handleDisconnect()
                }
            }
        }
    }

    private func handle(_ message: URLSessionWebSocketTask.Message) {
        let data: Data
        switch message {
        case .data(let d):
            data = d
        case .string(let s):
            data = Data(s.utf8)
        @unknown default:
            return
        }
        guard let chatMessage = try? JSONDecoder().decode(ChatMessage.self, from: data) else {
            return
        }
        messages.append(chatMessage)
    }

    private func handleDisconnect() {
        task = nil
        Task {
            try? await Task.sleep(nanoseconds: reconnectDelay)
            await MainActor.run { self.connect() }
        }
    }

    func send(text: String) {
        guard !text.isEmpty else { return }
        let message = ChatMessage(id: UUID().uuidString, author: "me", text: text)
        guard let data = try? JSONEncoder().encode(message) else { return }
        task?.send(.data(data)) { [weak self] error in
            guard error != nil else { return }
            Task { @MainActor in
                self?.handleDisconnect()
            }
        }
    }

    func disconnect() {
        task?.cancel(with: .goingAway, reason: nil)
        task = nil
    }
}

struct ChatScreen: View {
    @StateObject private var connection = ChatConnection()
    @State private var draft: String = ""

    var body: some View {
        VStack(spacing: 0) {
            ScrollViewReader { proxy in
                ScrollView {
                    LazyVStack(alignment: .leading, spacing: 8) {
                        ForEach(connection.messages) { message in
                            VStack(alignment: .leading, spacing: 2) {
                                Text(message.author)
                                    .font(.caption)
                                    .foregroundStyle(.secondary)
                                Text(message.text)
                            }
                            .id(message.id)
                            .padding(.horizontal)
                        }
                    }
                    .padding(.vertical, 8)
                }
                .onChange(of: connection.messages) { newMessages in
                    guard let lastId = newMessages.last?.id else { return }
                    withAnimation {
                        proxy.scrollTo(lastId, anchor: .bottom)
                    }
                }
            }

            Divider()

            HStack {
                TextField("Message", text: $draft)
                    .textFieldStyle(.roundedBorder)
                    .onSubmit(sendDraft)
                Button("Send", action: sendDraft)
                    .disabled(draft.isEmpty)
            }
            .padding()
        }
        .onAppear { connection.connect() }
        .onDisappear { connection.disconnect() }
    }

    private func sendDraft() {
        let text = draft.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty else { return }
        connection.send(text: text)
        draft = ""
    }
}
